import{I as i,o as u,c as d,j as t,a as o,J as s,w as a,b6 as g}from"./chunks/framework.BUXTSoD9.js";const h={style:{margin:"50px 0"}},m=JSON.parse('{"title":"إيجاد فكرة جيدة - من احتياجات المستخدمين إلى منتجات يدفعون مقابلها","description":"تعلم كيفية اكتشاف الفرص التجارية من نقاط الألم اليومية، وإتقان المنهجية النظامية لتحليل الاحتياجات، وصقل الأفكار العادية لتصبح مفاهيم منتجات يرغب المستخدمون في الدفع مقابلها.","frontmatter":{"title":"إيجاد فكرة جيدة - من احتياجات المستخدمين إلى منتجات يدفعون مقابلها","description":"تعلم كيفية اكتشاف الفرص التجارية من نقاط الألم اليومية، وإتقان المنهجية النظامية لتحليل الاحتياجات، وصقل الأفكار العادية لتصبح مفاهيم منتجات يرغب المستخدمون في الدفع مقابلها."},"headers":[],"relativePath":"ar-sa/stage-1/finding-great-idea/index.md","filePath":"ar-sa/stage-1/finding-great-idea/index.md"}'),q={name:"ar-sa/stage-1/finding-great-idea/index.md"},f=Object.assign(q,{setup(c){const r="حوالي <strong>3 ساعات</strong>";return(b,l)=>{const n=i("ChapterIntroduction"),p=i("StepBar"),e=i("ClientOnly");return u(),d("div",null,[l[1]||(l[1]=t("h1",{id:"المستوى-المبتدئ-الثاني-إيجاد-فكرة-جيدة",tabindex:"-1"},[o("المستوى المبتدئ الثاني: إيجاد فكرة جيدة "),t("a",{class:"header-anchor",href:"#المستوى-المبتدئ-الثاني-إيجاد-فكرة-جيدة","aria-label":"Permalink to “المستوى المبتدئ الثاني: إيجاد فكرة جيدة”"},"​")],-1)),l[2]||(l[2]=t("h2",{id:"مقدمة-الفصل",tabindex:"-1"},[o("مقدمة الفصل "),t("a",{class:"header-anchor",href:"#مقدمة-الفصل","aria-label":"Permalink to “مقدمة الفصل”"},"​")],-1)),s(n,{duration:r,tags:["اكتشاف الاحتياجات","تفكير المنتج","تحليل المستخدمين","نموذج العمل"],coreOutput:"3 مفاهيم منتجات تم التحقق منها",expectedOutput:"اتجاهات بدء مشروع/منتج قابلة للتنفيذ"},{default:a(()=>[...l[0]||(l[0]=[t("p",null,[o("في الفصل السابق، تعلمنا كيفية استخدام AI IDE لصنع الأشياء، ولكن هناك سؤال أكثر جوهرية: "),t("strong",null,"ماذا نصنع؟")],-1),t("p",null,[o('الكثير من الناس يفكرون فوراً في "صنع أداة AI" أو "بناء منصة اجتماعية"، والنتيجة هي أن لا أحد يستخدم ما صنعوه. أين تكمن المشكلة؟ '),t("strong",null,"لم يجدوا احتياجاً حقيقياً.")],-1),t("p",null,[o("والواقع أكثر قسوة هو: "),t("strong",null,"العديد من المنتجات تحل المشاكل، لكن المستخدمين ببساطة غير مستعدين للدفع مقابلها.")],-1),t("p",null,"في هذا الفصل، من خلال قصة شياو مينغ، سنتعلم كيفية إيجاد اتجاهات منتجات تستحق العناء.",-1),t("p",null,[o("بعد إكمال هذا الفصل، ستمتلك "),t("strong",null,"منهجية كاملة لإيجاد الأفكار"),o("، بالإضافة إلى 3 مفاهيم منتجات تم التحقق منها.")],-1)])]),_:1}),t("div",h,[s(e,null,{default:a(()=>[s(p,{active:0,items:[{title:"Step 1",description:"بناء معايير الحكم"},{title:"Step 2",description:"اكتشاف نقاط الألم اليومية"},{title:"Step 3",description:"التقسيم الأفقي للجمهور"},{title:"Step 4",description:"الحفر العمودي في السيناريوهات"},{title:"Step 5",description:"التحقق من صحة الاحتياجات"},{title:"Step 6",description:"صقل مفهوم المنتج"}]})]),_:1})]),l[3]||(l[3]=g(`<h2 id="step-1-بناء-معايير-الحكم-——-ما-نوع-الاحتياجات-التي-يدفع-المستخدمون-مقابلها" tabindex="-1">Step 1：بناء معايير الحكم —— ما نوع الاحتياجات التي يدفع المستخدمون مقابلها <a class="header-anchor" href="#step-1-بناء-معايير-الحكم-——-ما-نوع-الاحتياجات-التي-يدفع-المستخدمون-مقابلها" aria-label="Permalink to “Step 1：بناء معايير الحكم —— ما نوع الاحتياجات التي يدفع المستخدمون مقابلها”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">لماذا هذا الفصل مهم؟</p><p>قد يتساءل البعض: &quot;أليس هذا دورة لتعليم Vibe Coding؟ لماذا نتعلم &#39;إيجاد الاحتياجات&#39; أولاً؟ ألا يمكننا البدء بكتابة الكود مباشرة؟&quot;</p><p>في الواقع، العديد من دورات البرمجة في السوق تعلمك مباشرة كيفية تنفيذ المشاريع: صنع قائمة مهام، صنع آلة حاسبة، صنع مدونة شخصية... هذه المشاريع تساعد بالفعل في التعرف على بناء الجملة والأدوات، لكن المشكلة هي:</p><p><strong>إذا كان الاتجاه خاطئاً، كلما تعمقت أكثر، زاد الخطأ.</strong></p><p>تخيل:</p><ul><li>قضيت أسبوعين في صنع &quot;نظام إدارة تقويم&quot;، لكن هناك بالفعل 100 نظام أفضل في السوق</li><li>صنعت &quot;حاسباً للسعرات الحرارية بالتصوير&quot;، لكن المستخدم يحذفه بعد استخدام مرة واحدة</li><li>صنعت &quot;دفتر حسابات شخصي&quot;، لكن حتى أنت نفسك تتكاسل عن استخدامه</li></ul><p>بعد الانتهاء من هذه المشاريع، هل يمكنك كتابتها في سيرتك الذاتية؟ على الأرجح لا، لأن <strong>لم تحل مشاكل حقيقية، ولم تنتج قيمة حقيقية</strong>.</p><p>والأكثر قسوة هو: بما أننا سنستثمر وقتاً في التعلم، لماذا لا نسعى لتحقيق نتائج أفضل؟</p><p>بما أن Vibe Coding يتيح لنا تحويل الأفكار إلى منتجات بسرعة، فيجب أن نتعلم <strong>إيجاد الأفكار التي تستحق العناء</strong>. أن نتدرب بأقرب طريقة للواقع — ليس بصنع &quot;مشاريع تدريبية&quot;، بل بصنع &quot;منتجات يرغب الناس في استخدامها&quot;.</p><p>لهذا السبب يجب أن نتعلم أولاً &quot;إيجاد فكرة جيدة&quot;.</p><hr><p><strong>يرى الكاتب بشكل شخصي</strong> أن الوقت ثمين جداً، <strong>وبما أننا نفعل شيئاً، يجب أن نحقق أفضل نتيجة ممكنة</strong>، وإلا فلماذا لا نذهب للعب؟ وكمسؤولية، سيبذل الكاتب قصارى جهده لدعمك لتحقيق أفضل نتيجة.</p><p>حتى لو لم يكن أحد يؤمن بقدرتك على القيام بعمل جيد، سيظل الكاتب يأمل بثبات أن تتمكن من تحقيق أفضل نتيجة. بما أنك اخترت vibecoding لصنع منتجات، فجرب واكتشف إلى أين يمكنك الوصول!</p></div><hr><h2 id="الافتتاحية-قصة-شياو-مينغ-المبرمج-المستقل" tabindex="-1">الافتتاحية: قصة شياو مينغ المبرمج المستقل <a class="header-anchor" href="#الافتتاحية-قصة-شياو-مينغ-المبرمج-المستقل" aria-label="Permalink to “الافتتاحية: قصة شياو مينغ المبرمج المستقل”">​</a></h2><p>شياو مينغ مبرمج، يعمل منذ ثلاث سنوات. في يوم من الأيام خطرت له فكرة: ماذا لو صنع تطبيق لياقة بدنية، يساعد المستخدمين على وضع خطط تمارين وتسجيل بيانات التدريب. هذه الفكرة أثارته كثيراً، وشعر أنه وجد أخيراً مشروعاً يمكنه تنفيذه.</p><p>خلال العام التالي، خصص شياو مينغ تقريباً كل وقته الحر. صنع تطبيقاً بوظائف شاملة — وحدة دورات، نظام تسجيل حضور، وظائف مجتمعية، تحليل بيانات، كل ما يلزم موجود. الواجهة كانت جميلة أيضاً، على الأقل هو نفسه كان راضياً عنها.</p><p>في يوم الإطلاق، كان شياو مينغ مليئاً بالتوقعات. أنفق مبلغاً كبيراً على الترويج، وفي الشهر الأول كان هناك 50 ألف تحميل. يبدو أن البداية كانت جيدة، أليس كذلك؟</p><p>لكن المشاكل ظهرت بسرعة. بعد التحميل، يستخدم المستخدمون التطبيق مرة واحدة ثم يحذفونه، وكان معدل الاحتفاظ في اليوم السابع 5% فقط. صنع بعض الوظائف المدفوعة، لكن لم يكن هناك مستخدم مستعد لدفع المال. وما أحزنه أكثر هو أن منتجات ناضجة مثل Keep وBohe Health وFitTime، وظائفها أكثر شمولاً من تطبيقه، ومحتواها أفضل، فلماذا ينتقل المستخدمون إلى تطبيقه؟</p><p>بعد عام، خسر شياو مينغ 200 ألف.</p><p>جلس أمام الكمبيوتر، ينظر إلى البيانات الكئيبة في لوحة التحكم، ولم يكن في عقله سوى سؤال واحد: تطبيقي جيد جداً، لماذا لا أحد يستخدمه؟ والأكثر من ذلك، لماذا لا أحد مستعد للدفع؟</p><p>فشل شياو مينغ لم يكن بسبب ضعف مهاراته التقنية، ولا لأن المنتج سيء. بصراحة، وظائف تطبيقه كانت شاملة، والواجهة كانت جميلة.</p><p><strong>المشكلة كانت في نقطة البداية.</strong></p><p>لم يسأل أبداً السؤال الأكثر أساسية: هل المستخدمون يحتاجونه حقاً؟</p><p>رأى أن سوق تطبيقات اللياقة كبير، وتقييم Keep بمليارات، فاعتقد أن هذه فرصة جيدة. لكنه لم يوضح عدة أمور: لماذا يحتاج المستخدمون لتطبيق لياقة آخر؟ مقارنة بـ Keep، ما هو التمايز الخاص بي؟ هل المستخدمون مستعدون للدفع مقابل ذلك؟</p><p><strong>إذا كان الاتجاه خاطئاً، كلما تعمقت أكثر، زاد الخطأ.</strong> قضى عاماً في تطوير اتجاه خاطئ بشكل متزايد، والنتيجة كانت فقط الابتعاد أكثر عن النجاح.</p><div class="tip custom-block"><p class="custom-block-title">ماذا نفعل في هذا الفصل</p><p>في هذا الفصل، سنساعد شياو مينغ على إجراء مراجعة. لنرى أين تكمن مشكلته بالضبط، ثم نجد معاً اتجاهات منتجات حقيقية يدفع الناس مقابلها.</p><p>سنمضي في ثلاث خطوات:</p><p><strong>المشهد الأول: إيجاد الاحتياج الحقيقي</strong> — أولاً نفهم بوضوح ما نوع الاحتياجات التي يدفع المستخدمون مقابلها</p><p><strong>المشهد الثاني: استخراج فكرة جيدة</strong> — تعلم كيفية استخراج فرص تجارية قيمة من الأفكار العادية</p><p><strong>المشهد الثالث: صقل عبر حوار AI</strong> — استخدام AI لتحويل الأفكار إلى خطط منتجات قابلة للتنفيذ</p></div><hr><h2 id="المشهد-الأول-إيجاد-الاحتياج-الحقيقي" tabindex="-1">المشهد الأول: إيجاد الاحتياج الحقيقي <a class="header-anchor" href="#المشهد-الأول-إيجاد-الاحتياج-الحقيقي" aria-label="Permalink to “المشهد الأول: إيجاد الاحتياج الحقيقي”">​</a></h2><p>كان شياو مينغ محبطاً، لكنه لم يستسلم. بدأ في التفكير في سؤال: ما نوع الاحتياجات التي يدفع المستخدمون مقابلها فعلاً؟</p><h3 id="حيرة-شياو-مينغ-لماذا-لا-يدفع-المستخدمون؟" tabindex="-1">حيرة شياو مينغ: لماذا لا يدفع المستخدمون؟ <a class="header-anchor" href="#حيرة-شياو-مينغ-لماذا-لا-يدفع-المستخدمون؟" aria-label="Permalink to “حيرة شياو مينغ: لماذا لا يدفع المستخدمون؟”">​</a></h3><p>ذهب إلى عدة أصدقاء استخدموا تطبيقه، ليستمع إلى أفكارهم الحقيقية.</p><p>قال الصديق أ: &quot;تطبيقك جيد جداً، لكنني أستخدم Keep بالفعل، لماذا أنتقل؟&quot;</p><p>قال الصديق ب: &quot;تطلب مني تسجيل كل تمرين، هذا مزعج جداً، وأنا كسول للتسجيل.&quot;</p><p>قال الصديق ج بشكل أكثر مباشرة: &quot;الوظائف المجانية كافية، لماذا أدفع؟&quot;</p><p>هذه الإجابات جعلت شياو مينغ يفهم المشكلة فجأة.</p><p><strong>المشكلة الأولى: المستخدمون لا ينتقلون، لأن الحلول الحالية كافية بالفعل.</strong> منتجات ناضجة مثل Keep وظائفها شاملة بالفعل، وعادات المستخدمين تكونت، وتكلفة الانتقال عالية. تصنع منتجاً مشابهاً، فبماذا تقنع المستخدم بالانتقال؟</p><p><strong>المشكلة الثانية: المستخدمون غير مستعدين لتغيير عاداتهم.</strong> تسجيل التمارين أمر مزعج جداً للمستخدمين. إذا كان المنتج يتطلب من المستخدم تغيير أكثر من 3 عادات، فمن المرجح أن يفشل.</p><p><strong>المشكلة الثالثة: البدائل المجانية كثيرة جداً.</strong> وظائفك عامة جداً، بدون قيمة فريدة، والمستخدمون لا يجدون سبباً للدفع.</p><h3 id="ما-هو-الاحتياج-الحقيقي؟" tabindex="-1">ما هو الاحتياج الحقيقي؟ <a class="header-anchor" href="#ما-هو-الاحتياج-الحقيقي؟" aria-label="Permalink to “ما هو الاحتياج الحقيقي؟”">​</a></h3><p>بدأ شياو مينغ في دراسة المنتجات الناجحة التي يجد المستخدمون أنفسهم مستعدين للدفع مقابلها. اكتشف نقطة مشتركة: هذه المنتجات لا تحل احتياجات من نوع &quot;أعتقد أنها مفيدة&quot;، بل احتياجات يدفع المستخدمون مقابلها، ويغيرون سلوكهم من أجلها، ويتحملون الإزعاج من أجلها.</p><p>بعبارة أخرى، <strong>الاحتياج الحقيقي هو ما يصوت عليه المستخدمون بأقدامهم، وليس ما يفكر فيه مدير المنتج من فراغ.</strong></p><h3 id="حالات-منتجات-يجد-المستخدمون-أنفسهم-مدفوعين-مقابلها" tabindex="-1">حالات: منتجات يجد المستخدمون أنفسهم مدفوعين مقابلها <a class="header-anchor" href="#حالات-منتجات-يجد-المستخدمون-أنفسهم-مدفوعين-مقابلها" aria-label="Permalink to “حالات: منتجات يجد المستخدمون أنفسهم مدفوعين مقابلها”">​</a></h3><p>درس شياو مينغ عدة حالات ناجحة، ليفهم بالضبط ما هي نقاط الألم التي التقطتها.</p><h4 id="meicai-دع-أصحاب-المطاعم-الصغيرة-ينامون-نوماً-هنيئاً" tabindex="-1">Meicai: دع أصحاب المطاعم الصغيرة ينامون نوماً هنيئاً <a class="header-anchor" href="#meicai-دع-أصحاب-المطاعم-الصغيرة-ينامون-نوماً-هنيئاً" aria-label="Permalink to “Meicai: دع أصحاب المطاعم الصغيرة ينامون نوماً هنيئاً”">​</a></h4><p>على السطح، ما يفعله Meicai بسيط جداً: مساعدة المطاعم في شراء الخضروات. لكن إذا فكرت بعمق، لماذا يستخدمه أصحاب المطاعم؟</p><p>لأن أصحاب المطاعم الصغيرة يجب أن يستيقظوا في الساعة 4 فجراً للذهاب إلى سوق الجملة، هذا متعب جداً، وغالباً ما يتم خداعهم. ما يفعله Meicai ليس مجرد &quot;تجارة إلكترونية لبيع الخضروات&quot;، بل إعادة هيكلة سلسلة التوريد بأكملها، مما يسمح لأصحاب المطاعم الصغيرة بالنوم نوماً هنيئاً.</p><p>كلما كانت نقطة الألم أشد، كانت الرغبة في الدفع أقوى. الوقت والجهد الموفّرين أكثر قيمة من المال الموفر في شراء الخضروات.</p><h4 id="xiaohongshu-حل-صعوبة-الاختيار" tabindex="-1">Xiaohongshu: حل صعوبة الاختيار <a class="header-anchor" href="#xiaohongshu-حل-صعوبة-الاختيار" aria-label="Permalink to “Xiaohongshu: حل صعوبة الاختيار”">​</a></h4><p>على السطح، Xiaohongshu هو &quot;مشاركة تجارب التسوق من الخارج&quot;. لكن لماذا يرغب المستخدمون في قضاء الوقت في قراءة الملاحظات عليه؟ لأن المستخدمين، عند مواجهة كم هائل من المنتجات، لا يعرفون ما يستحق الشراء وما لا يستحقونه. هم بحاجة إلى شخص يثقون به ليساعدهم في الفرز، وتوفير الوقت، وتجنب الوقوع في الأخطاء.</p><p>ما يحله تطبيق Xiaohongshu في الواقع هو نقطتا ألم عميقتان: صعوبة الاختيار وانعدام الثقة. فالمستخدمون على استعداد لدفع المال مقابل &quot;توفير الوقت&quot; و&quot;تجنب الأخطاء&quot;، وهذا هو السبب الذي جعل Xiaohongshu ينجح.</p><hr><p>بعد قراءة هذه الحالات، توصل شياو مينغ إلى اكتشاف مهم.</p><p>ما يدفع المستخدمون ثمنه لم يكن أبداً &quot;الميزات&quot;، بل &quot;حل المخاوف&quot; و&quot;إزالة القلق&quot;. ما حله موقع MeiCai كان الخوف الذي يشعر به أصحاب المطاعم الصغيرة من مشقة الشراء في الصباح الباكر، وما حله تطبيق Xiaohongshu كان خوف المستخدمين من شراء الأشياء الخطأ.</p><p><strong>الخوف هو ما يحفز الدفع، والقلق هو ما يحفز العمل.</strong></p><h3 id="مستويات-الاحتياجات-الثلاثة-نقاط-الألم،-نقاط-المتعة،-ونقاط-الرغبة" tabindex="-1">مستويات الاحتياجات الثلاثة: نقاط الألم، نقاط المتعة، ونقاط الرغبة <a class="header-anchor" href="#مستويات-الاحتياجات-الثلاثة-نقاط-الألم،-نقاط-المتعة،-ونقاط-الرغبة" aria-label="Permalink to “مستويات الاحتياجات الثلاثة: نقاط الألم، نقاط المتعة، ونقاط الرغبة”">​</a></h3><p>أجرى شياو مينغ المزيد من البحث ووجد أن احتياجات المستخدمين يمكن تقسيمها إلى ثلاثة أنواع:</p><div class="tip custom-block"><p class="custom-block-title">نقاط الألم (Pain Point) —— يحفزها الخوف</p><p><strong>الجوهر:</strong> المشاكل التي يمر بها المستخدمون والتي تجعلهم يشعرون بالألم والقلق وعدم الراحة. عدم حلها يسبب انزعاجاً شديداً، بل وقد يهدد البقاء أو السلامة.</p><p><strong>أمثلة:</strong></p><ul><li>مرضى السكري لا يعرفون كمية الكربوهيدرات التي سترفع مستوى السكر في الدم لديهم (الخوف: تهديد صحي)</li><li>أصحاب المطاعم الصغيرة يستيقظون في الساعة 4 صباحاً للذهاب إلى سوق الجملة (الخوف: مشقة البقاء)</li></ul><p><strong>النقطة الأساسية:</strong> المستخدمون على استعداد لدفع المال لحل هذه المشاكل، لأن عدم حلها &quot;مؤلم جداً&quot;.</p></div><div class="tip custom-block"><p class="custom-block-title">نقاط المتعة (Delight Point) —— الإشباع الفوري</p><p><strong>الجوهر:</strong> لدى المستخدم حاجة يمكن تلبيتها على الفور، مما يولد شعوراً فورياً بالرضا والسعادة.</p><p><strong>أمثلة:</strong></p><ul><li>توصيل الطلبات الخارجية في 30 دقيقة (الإشباع الفوري للجوع)</li><li>إنشاء عرض تقديمي (PPT) أنيق بضغطة واحدة (شعور بالمتعة لتوفير الوقت والجهد)</li></ul><p><strong>النقطة الأساسية:</strong> جعل المستخدم يشعر &quot;بالمتعة&quot; هو مفتاح الاحتفاظ به، لكنها تعتبر نقطة دفع ضعيفة إذا كانت وحدها.</p></div><div class="tip custom-block"><p class="custom-block-title">نقاط الرغبة (Itch Point) —— الذات الافتراضية</p><p><strong>الجوهر:</strong> يرغب المستخدم في أن يصبح أفضل، أو أروع، أو أكثر رقيًا، لكنها ليست ضرورية. فإذا تم تلبيتها سيكون سعيداً، وإذا لم تُلبَّى فلا مشكلة في ذلك.</p><p><strong>أمثلة:</strong></p><ul><li>تسجيل كمية المياه التي يشربها يومياً (تخيل حياة مليئة بالانضباط الذاتي)</li><li>استخدام الذكاء الاصطناعي لإضافة فلاتر فنية للصور (تخيل ذوق فني)</li></ul><p><strong>النقطة الأساسية:</strong> رغبة المستخدمين في الدفع مقابل &quot;نقاط الرغبة&quot; ضعيفة، لأنه لا توجد مشكلة حقيقية إذا لم يتم حلها.</p></div><p>كيف ننظر إلى الترتيب الصحيح للأولويات؟ نصيحة جيدة هي: نقاط الألم &gt; نقاط المتعة &gt; نقاط الرغبة</p><p>لماذا؟</p><ol><li><strong>نقاط الألم هي احتياجات للبقاء:</strong> عدم حلها قد يؤدي إلى الهلاك (أو انزعاج شديد)، والمستخدمون مضطرون للدفع مقابلها. إنها &quot;مسكنات الألم&quot;.</li><li><strong>نقاط المتعة هي مكافآت فورية:</strong> تجعل المستخدم يشعر بالمتعة، والمستخدمون سيأتون من أجلها. إنها &quot;الهيروين&quot; (بمعنى آلية الإدمان الإيجابية).</li><li><strong>نقاط الرغبة هي تلبية للرغبات:</strong> يمكن الاستغناء عنها، وهي الأسهل في التخلي عنها. إنها &quot;الفيتامينات&quot; أو &quot;الكماليات&quot;.</li></ol><p><strong>رؤية أساسية:</strong> الخطأ الذي يقع فيه العديد من مديري المنتجات هو: استخدام طريقة بيع نقاط الألم لتسويق منتج يعالج نقاط الرغبة.</p><p>على سبيل المثال: &quot;تسجيل شرب الماء يجعلك أكثر صحة&quot; —— شرب الماء صحي بالفعل، لكن عدم تسجيله لن يجعلك غير صحي. هذا هو تغليف نقطة الرغبة في صورة نقطة ألم، والمستخدمون لن يقبلوا ذلك.</p><h3 id="طريقة-من-5-خطوات-للتحقق-من-الاحتياجات-الحقيقية" tabindex="-1">طريقة من 5 خطوات للتحقق من الاحتياجات الحقيقية <a class="header-anchor" href="#طريقة-من-5-خطوات-للتحقق-من-الاحتياجات-الحقيقية" aria-label="Permalink to “طريقة من 5 خطوات للتحقق من الاحتياجات الحقيقية”">​</a></h3><p>فكر شياو مينغ: <strong>إذن، عندما يكون لدي فكرة، كيف أحكم بسرعة على ما إذا كانت تستحق الاستثمار؟</strong></p><p>لقد تعلم طريقة الحكم المكونة من 5 خطوات والتي يستخدمها مديرو المنتجات (للمحتوى التفصيلي، راجع الملحق أ):</p><ol><li><p><strong>الخطوة الأولى: تحدث مباشرة مع المستخدمين الحقيقيين لمعرفة كيف يفعلون الأشياء حالياً</strong></p><p>اعثر على 10 مستخدمين مستهدفين. اسألهم: &quot;كيف تحل هذه المشكلة الآن؟&quot; إذا كان المستخدمون يستخدمون بالفعل طريقة ما، فهذا يعني أن المشكلة موجودة بالفعل. وإذا قال المستخدمون إنهم لا يحتاجون إلى حل، فقد لا تكون هذه حاجة حقيقية.</p></li><li><p><strong>الخطوة الثانية: حلل الحلول البديلة الحالية للمستخدمين واكتشف ميزتك</strong></p><p>قد يستخدم المستخدمون حالياً منتجات أخرى، أو Excel، أو يعتمدون على الذاكرة، أو يتحملون عدم وجود حل. تحتاج إلى معرفة عيوب هذه الحلول. يجب أن يكون منتجك أفضل بكثير منها حتى يرغب المستخدمون في التبديل.</p></li><li><p><strong>الخطوة الثالثة: اختبر ما إذا كان المستخدمون على استعداد لدفع المال مقابل منتجك</strong></p><p>قم بالبيع المسبق أو اجمع عربوناً. احسب نسبة المستخدمين المستعدين لدفع عربون (كلما كسبت المال في وقت مبكر، كان ذلك دليلاً على صحة الاحتياج):</p><ul><li>أكثر من 10%: الاحتياج حقيقي ويستحق الاستثمار</li><li>من 5% إلى 10%: الاحتياج موجود، لكنه يحتاج إلى صقل</li><li>أقل من 5%: الاحتياج قد لا يكون صحيحاً</li></ul></li><li><p><strong>الخطوة الرابعة: قدّر حجم هذا السوق وما إذا كان يمكن تحقيق أرباح منه</strong></p><p>احسب ثلاثة أرقام: إجمالي المستخدمين المستهدفين × الاستعداد للدفع × متوسط قيمة الطلب. اضربهم لتحصل على حجم السوق. إذا كان السوق صغيراً جداً، فقد لا يستحق المجازفة.</p></li><li><p><strong>الخطوة الخامسة: فكر في الخندق الدفاعي (الميزة التنافسية) لمنتجك لمنع الآخرين من نسخه</strong></p><p>ضع في اعتبارك هذه الحواجز: الصعوبة التقنية، تأثيرات الشبكة، العلامة التجارية، ميزة التكلفة. هذه ستساعدك على الحفاظ على قدرتك التنافسية على المدى الطويل.</p></li></ol><p><strong>ملخص هذا الفصل: مكاسب شياو مينغ</strong></p><ol><li><p><strong>معيار الاحتياج الحقيقي</strong></p><ul><li>المعيار الأهم هو استعداد المستخدم للدفع.</li><li>المستخدم على استعداد لتغيير سلوكه من أجله.</li><li>في حالة عدم وجود حل، سيتكبد المستخدم خسارة كبيرة.</li></ul></li><li><p><strong>تجنب الاحتياجات الزائفة</strong></p><ul><li>نقاط الرغبة ليست نقاط ألم، ولا يمكن معاملتها كاحتياجات حقيقية.</li><li>إذا كان السوق صغيراً جداً، فمن الصعب الحفاظ على نموذج عمل.</li><li>إذا كان الحل أكثر تعقيداً من المشكلة، فسيتخلى المستخدمون عنه.</li></ul></li><li><p><strong>ترتيب الأولويات</strong></p><ul><li>الأولوية الحقيقية هي: نقاط الألم &gt; نقاط المتعة &gt; نقاط الرغبة.</li></ul></li></ol><p><strong>مخرجات هذا الفصل</strong></p><ul><li>لقد فهمت ما هو الاحتياج الحقيقي.</li><li>لقد أتقنت التصنيف ثلاثي المستويات للاحتياجات: نقاط الألم، نقاط المتعة، ونقاط الرغبة.</li><li>لقد تعلمت كيفية استخدام طريقة الحكم المكونة من 5 خطوات للتحقق من صحة الاحتياجات.</li></ul><hr><h2 id="الفصل-الثاني-استخراج-الأفكار-الجيدة" tabindex="-1">الفصل الثاني: استخراج الأفكار الجيدة <a class="header-anchor" href="#الفصل-الثاني-استخراج-الأفكار-الجيدة" aria-label="Permalink to “الفصل الثاني: استخراج الأفكار الجيدة”">​</a></h2><p>يعرف شياو مينغ الآن ما هو الاحتياج الحقيقي، لكنه لا يزال لا يعرف من أين يبدأ. لا يمكنه ببساطة اختلاق احتياج من العدم، أليس كذلك؟</p><p>قرر أن يبدأ من الأشياء الأكثر ألفة بالنسبة له —— الأشخاص والأحداث من حوله.</p><h3 id="البدء-من-نفسه-أخت-شياو-مينغ-الكبرى" tabindex="-1">البدء من نفسه: أخت شياو مينغ الكبرى <a class="header-anchor" href="#البدء-من-نفسه-أخت-شياو-مينغ-الكبرى" aria-label="Permalink to “البدء من نفسه: أخت شياو مينغ الكبرى”">​</a></h3><p>تذكر شياو مينغ أخته الكبرى. فقد أنجبت طفلاً مؤخراً، وكانت دائماً تشكو من عدم وجود وقت للتمارين الرياضية، ومن عدم قدرتها على التخلص من دهون البطن، وكانت تشعر بالقلق الشديد بشكل عام.</p><p>في أحد الأيام سألها: &quot;كيف تحلين مشكلة اللياقة البدنية الآن؟&quot;</p><p>تنهدت الأخت وقالت: &quot;أتابع تمارين تطبيق Keep، لكن تلك الحركات لا تناسب الجسم بعد الولادة، وبعد الانتهاء منها يزداد ألم ظهري. الذهاب إلى الصالة الرياضية؟ لا يوجد أحد لمساعدتي في رعاية الطفل. استمدار مدرب شخصي؟ تبلغ تكلفة الحصة الواحدة من 300 إلى 500 يوان، وهذا مكلف جداً. والتمرن بشكل عشوائي بمفردي، أخاف من الإصابة.&quot;</p><p>بعد الاستماع إلى ذلك، شعر شياو مينغ أن هذا قد يكون الاحتياج الحقيقي الذي يبحث عنه.</p><p>مشاكل أخته الكبرى في الواقع محددة جداً: الوقت مجزأ، وتحتاج إلى رعاية الطفل، ولا يوجد وقت متواصل لممارسة الرياضة؛ الجسم به قيود، وانفصال عضلات البطن المستقيمة وارتخاء عضلات قاع الحوض يمنعها من ممارسة الرياضة العنيفة؛ تشعر بقلق نفسي كبير بسبب تغير شكل جسمها، وتخشى أن تنفر منها زوجها، ولديها عقدة نقص اجتماعية؛ المعلومات مشوشة للغاية، فهناك الكثير من المعلومات على الإنترنت، ولا تعرف أي التمارين مناسبة لمرحلة ما بعد الولادة؛ وهناك أيضاً الشعور بالوحدة، فلا أحد يفهم وضعها، وتنعدم الدعم من الأقران.</p><p>كل هذه نقاط ألم حقيقية، وليست مجرد &quot;نقاط رغبة&quot; من نوعية &quot;سيكون من الجيد أن تتوفر&quot;.</p><hr><h3 id="التقسيم-الأفقي-احتياجات-الفئات-المختلفة" tabindex="-1">التقسيم الأفقي: احتياجات الفئات المختلفة <a class="header-anchor" href="#التقسيم-الأفقي-احتياجات-الفئات-المختلفة" aria-label="Permalink to “التقسيم الأفقي: احتياجات الفئات المختلفة”">​</a></h3><p>أدرك شياو مينغ أن فكرة &quot;تطبيق لياقة بدنية&quot; واسعة جداً. إنه يريد مساعدة الجميع على ممارسة الرياضة، ولكن المشكلة هي أن احتياجات الجميع مختلفة.</p><p>قام بعمل تقسيم أفقي، وقسم &quot;الأشخاص الذين يرغبون في ممارسة الرياضة&quot; إلى عدة فئات (للحصول على التفاصيل، راجع الملحق ب):</p><p>تحتاج فئة بناء العضلات إلى حساب دقيق لكمية البروتين التي يتناولونها، والتسجيل اليدوي متعب جداً، ولديهم استعداد عالٍ للدفع، ويسعون وراء الكفاءة. يجب على مرضى السكري التحكم بصرامة في الكربوهيدرات، لكن من الصعب تقديرها عند تناول الطعام بالخارج، وهذا احتياج أساسي، ومستعدون للدفع، ومعدل إعادة الشراء مرتفع. ترغب الأمهات بعد الولادة في استعادة قوامهن ولكن ليس لديهن وقت للحساب، ويحتاجن إلى حلول بسيطة، وهن حساسات للوقت، ويحتجن إلى خدمة شاملة. فئة الطلبات الجاهزة تتناول الطعام الجاهز يومياً ولا تعرف عدد السعرات الحرارية التي استهلكتها، وهذا سيناريو متكرر، لكن الاستعداد للدفع متوسط. يحتاج طلاب الدراسات العليا إلى أدوات تعليمية فعالة، لكنهم لا يعرفون ماذا يستخدمون، وهذا احتياج أساسي، لكن متوسط قيمة الطلب منخفض.</p><p>اختار شياو مينغ فئة &quot;الأمهات بعد الولادة&quot;. لماذا؟</p><p>أولاً، هو نفسه يمثل المستخدم —— أخته الكبرى هي أم بعد الولادة، وهو يفهم بطبيعته نقاط ألم هذه المجموعة. ثانياً، نقاط الألم مؤلمة جداً —— القلق بشأن التعافي بعد الولادة حقيقي، وليس مجرد &quot;نقطة رغبة&quot; من نوعية &quot;سيكون من الجيد أن تتوفر&quot;. ثالثاً، الاستعداد القوي للدفع —— الأمهات على استعداد لإنفاق المال لاستعادة قوامهن. رابعاً، المنافسة ليست شرسة نسبياً —— لا توجد منتجات في السوق مخصصة خصيصاً للأمهات بعد الولادة.</p><div class="tip custom-block"><p class="custom-block-title">منطق التقسيم لدى مدير المنتج</p><p>لماذا يعتبر تقسيم الفئات المستهدفة مهماً جداً؟</p><p>لأن الأدوات العامة يصعب أن تنتصر. فقد احتلت المنصات الكبرى بالفعل سوق &quot;المنتجات العامة&quot;، ومن الصعب جداً التفوق عليها في الوظائف. احتياجات الفئات المتخصصة أكثر ألماً —— احتياج الأمهات بعد الولادة لللياقة البدنية هو احتياج أساسي، بينما بالنسبة لممارس اللياقة العاديين هو مجرد &quot;أمر جيد&quot;. خدمة مجموعة صغيرة بشكل جيد أسهل في بناء سمعة جيدة من محاولة إرضاء الجميع. نقاط ألم الفئات المتخصصة أكثر تحديداً، وهم أكثر استعداداً للدفع مقابل الحلول.</p></div><hr><h3 id="الحفر-العمودي-سيناريو-المستخدم-الكامل" tabindex="-1">الحفر العمودي: سيناريو المستخدم الكامل <a class="header-anchor" href="#الحفر-العمودي-سيناريو-المستخدم-الكامل" aria-label="Permalink to “الحفر العمودي: سيناريو المستخدم الكامل”">​</a></h3><p>بعد العثور على الفئة المستهدفة، لم يتوقف شياو مينغ عند وظيفة &quot;اللياقة البدنية بعد الولادة&quot; فقط. أراد أن يفهم السيناريو الكامل للمستخدم بعمق أكبر (للحصول على التفاصيل، راجع الملحق ج).</p><p>لقد راقب الحياة اليومية لأخته الكبرى.</p><p>في الساعة 6 صباحاً، نام الطفل للتو، وكان لدى أخته 30 دقيقة من الفراغ. أرادت ممارسة الرياضة، لكنها خشيت أن توقظ طفلها، ولم تكن تعرف الحركات الآمنة التي يمكنها القيام بها.</p><p>في الساعة 10 صباحاً، كانت أخت شياو مينغ تحمل طفلها لتنويمه، وكان ظهرها يؤلمها كثيراً. أرادت القيام ببعض تمارين الإصلاح، لكن يديها ليستا فارغتين.</p><p>في الساعة 3 مساءً، نام الطفل، وأرادت الأخت ممارسة الرياضة. لكن جسدها كان متعباً جداً، ولم تكن تعرف ما إذا كانت لا تزال قادرة على ذلك.</p><p>في الساعة 8 مساءً، أصبحت الأخت أخيراً متفرغة، لكنها كانت قلقة جداً. نظرت إلى نفسها في المرآة، وشعرت أن حياتها قد انتهت، وبكت سراً وهي تتصفح صورها القديمة.</p><p>اكتشف شياو مينغ أن نقطة ألم أخته لم تكن &quot;عدم وجود دورات لياقة بدنية&quot;، بل &quot;الخوف والقلق بشأن التعافي بعد الولادة&quot;.</p><hr><div class="info custom-block"><p class="custom-block-title">التفكير السينمائي لمدير المنتج</p><p>يعتقد الكثير من الناس أن نقاط الألم هي مجرد احتياجات وظيفية، لكن هذا ليس صحيحاً. نقاط الألم هي المشاعر في السيناريو مضافة إلى الاستعداد للدفع.</p><p>عندما تنظر الأمهات بعد الولادة إلى أجسادهن المتغيرة في المرآة، فإن نقطة الألم الحقيقية ليست &quot;عدم معرفة كيفية ممارسة الرياضة&quot;، بل الخوف —— القلق من عدم التعافي الجيد للجسم وترك آثار جانبية؛ والقلق —— النظر إلى أنفسهن في المرآة والشعور بأن حياتهن قد انتهت؛ والعجز —— عدم معرفة من أين تبدأ وعدم وجود من يوجههن؛ والوحدة —— الجميع يلد بسهولة، بينما أحتاج أنا إلى وقت طويل للتعافي.</p><p>التصميم الجيد للمنتج يجب أن يحل المشاعر، وليس فقط الوظائف. فوراء المشاعر تكمن قوة دفع المستخدم للدفع.</p></div><hr><h3 id="إعادة-هيكلة-القيمة-من-تطبيق-لياقة-بدنية-إلى-مساعد-تعافي-الأمهات-بعد-الولادة" tabindex="-1">إعادة هيكلة القيمة: من &quot;تطبيق لياقة بدنية&quot; إلى &quot;مساعد تعافي الأمهات بعد الولادة&quot; <a class="header-anchor" href="#إعادة-هيكلة-القيمة-من-تطبيق-لياقة-بدنية-إلى-مساعد-تعافي-الأمهات-بعد-الولادة" aria-label="Permalink to “إعادة هيكلة القيمة: من &quot;تطبيق لياقة بدنية&quot; إلى &quot;مساعد تعافي الأمهات بعد الولادة&quot;”">​</a></h3><p>بناءً على التحليل أعلاه، أعاد شياو مينغ تصميم هذا المنتج.</p><div class="tip custom-block"><p class="custom-block-title">مفهوم المنتج بعد إعادة الهيكلة: &quot;مساعد تعافي الأمهات بعد الولادة&quot;</p><p><strong>التموضع الأساسي:</strong> ليس مجرد أداة للياقة البدنية، بل &quot;مدرب إعادة تأهيل حصري + داعم نفسي&quot; للأمهات بعد الولادة</p><p><strong>الوظائف الأساسية:</strong></p><ol><li><p><strong>تمارين مجزأة:</strong></p><ul><li>تستغرق كل مرة 10-15 دقيقة فقط</li><li>يمكن ممارستها حتى أثناء نوم الطفل</li><li>توفير حركات &quot;يمكن القيام بها أثناء حمل الطفل&quot;</li></ul></li><li><p><strong>دورات مخصصة لما بعد الولادة:</strong></p><ul><li>مصنفة حسب مرحلة ما بعد الولادة (0-3 أشهر، 3-6 أشهر، أكثر من 6 أشهر)</li><li>تمارين مخصصة لانفصال عضلات البطن المستقيمة وإصلاح عضلات قاع الحوض</li><li>كل حركة بها تنبيهات &quot;احتياطات ما بعد الولادة&quot;</li></ul></li><li><p><strong>تصحيح الحركات بالذكاء الاصطناعي:</strong></p><ul><li>التعرف على الحركات عبر كاميرا الهاتف</li><li>تنبيهات فورية مثل &quot;الركبتان مثنيتان كثيراً&quot;، &quot;يجب إبقاء الظهر مستقيماً&quot;</li><li>تجنب الإصابات الناتجة عن الحركات الخاطئة</li></ul></li><li><p><strong>مجتمع الدعم النفسي:</strong></p><ul><li>مجتمع خاص بالأمهات بعد الولادة فقط</li><li>مشاركة تقدم التعافي والتشجيع المتبادل</li><li>انضمام مستشارين نفسيين محترفين</li></ul></li><li><p><strong>خطط مخصصة:</strong></p><ul><li>مصممة حسب طريقة الولادة (طبيعية/قيصرية) والحالة الجسدية</li><li>مراعاة الاحتياجات الخاصة لفترة الرضاعة</li></ul></li></ol><p><strong>نموذج الأعمال:</strong></p><ul><li>الدورات الأساسية مجانية</li><li>الدورات المتقدمة: 99 يوان/شهر (تشمل تصحيح الحركات بالذكاء الاصطناعي وخطط مخصصة)</li><li>مدرب خاص فردي: 299 يوان/شهر (توجيه عبر الإنترنت)</li><li>عضوية المجتمع: 199 يوان/سنة (تشمل الدعم النفسي وإجابات الخبراء)</li></ul><p><strong>مزايا تنافسية:</strong></p><ul><li>الاحترافية: التعاون مع مؤسسات إعادة التأهيل بعد الولادة، مع دعم طبي</li><li>تماسك المجتمع: الرابط العاطفي بين الأمهات بعد الولادة قوي جداً</li><li>تراكم البيانات: كلما زادت بيانات المستخدمين الجسدية، أصبحت الخطط أكثر دقة</li></ul><p><strong>حجم السوق:</strong></p><ul><li>حوالي 10 مليون مولود جديد سنوياً في الصين</li><li>سوق إعادة التأهيل بعد الولادة حوالي 50 مليار يوان</li><li>الهدف: خدمة 1% من الأمهات بعد الولادة = 100,000 مستخدم</li><li>ARPU (متوسط الإيرادات لكل مستخدم): 500 يوان/سنة</li><li>الإيرادات المحتملة: 50 مليون يوان/سنة</li></ul></div><p>مقارنة بين الفكرة الأصلية والمفهوم بعد إعادة الهيكلة:</p><table tabindex="0"><thead><tr><th>البُعد</th><th>الفكرة الأصلية</th><th>بعد إعادة الهيكلة</th></tr></thead><tbody><tr><td>المستخدمون المستهدفون</td><td>جميع ممارسي اللياقة (عام جداً)</td><td>الأمهات بعد الولادة (محدد بدقة)</td></tr><tr><td>حل المشكلة</td><td>تسجيل التمارين (رغبة ثانوية)</td><td>قلق التعافي بعد الولادة (مشكلة حقيقية)</td></tr><tr><td>المزايا التنافسية</td><td>التكنولوجيا (سهلة النسخ)</td><td>الاحترافية + المجتمع + البيانات</td></tr><tr><td>الاستعداد للدفع</td><td>منخفض (بدائل مجانية كثيرة)</td><td>مرتفع (حاجة أساسية + قيمة عاطفية)</td></tr><tr><td>مساحة التوسع</td><td>محدودة</td><td>يمكن التوسع لفترة الحمل وما قبل الحمل</td></tr></tbody></table><p><strong>هذا هو التطور من &quot;مجرد وظيفة&quot; إلى &quot;منتج يدفع الناس مقابله&quot;.</strong></p><hr><h3 id="المزيد-من-الأمثلة-من-الفكرة-العادية-إلى-الفكرة-الجيدة" tabindex="-1">المزيد من الأمثلة: من الفكرة العادية إلى الفكرة الجيدة <a class="header-anchor" href="#المزيد-من-الأمثلة-من-الفكرة-العادية-إلى-الفكرة-الجيدة" aria-label="Permalink to “المزيد من الأمثلة: من الفكرة العادية إلى الفكرة الجيدة”">​</a></h3><p>شعر شياو مينغ أن هذه الطريقة مفيدة جداً. فاستخدم نفس الطريقة لتحليل بعض الأمثلة الأخرى، لمعرفة ما إذا كانت هذه الطريقة عامة وقابلة للتطبيق (للحالات التفصيلية راجع الملحق د).</p><h4 id="المثال-الأول-من-قياس-السعرات-الحرارية-إلى-كل-بأمان-يا-صديق-السكري" tabindex="-1">المثال الأول: من &quot;قياس السعرات الحرارية&quot; إلى &quot;كل بأمان يا صديق السكري&quot; <a class="header-anchor" href="#المثال-الأول-من-قياس-السعرات-الحرارية-إلى-كل-بأمان-يا-صديق-السكري" aria-label="Permalink to “المثال الأول: من &quot;قياس السعرات الحرارية&quot; إلى &quot;كل بأمان يا صديق السكري&quot;”">​</a></h4><p>الفكرة العادية هي التقاط صور للطعام للتعرف على السعرات الحرارية ومساعدة الأشخاص في إنقاص الوزن والتحكم في النظام الغذائي. لكن المشكلة أن هناك منتجات ناضجة بالفعل في السوق مثل بوها جيانكانغ (Boohee) و MyFitnessPal.</p><p>قام شياو مينغ بالتقسيم الأفقي ووجد أن فئة مرضى السكري مثيرة للاهتمام: يجب عليهم التحكم بشكل صارم في الكربوهيدرات، لكن من الصعب تقديرها عند تناول الطعام بالخارج. وعند الحفر العمودي في سيناريوهاتهم: قبل الوجبة لا يعرفون ما إذا كان بإمكانهم أكل هذا الطبق، ويقلقون من ارتفاع السكر في الدم؛ أثناء الوجبة يحتاجون إلى تذكير فوري &quot;كم كربوهيدرات تناولت بالفعل&quot;؛ وبعد الوجبة يحتاجون إلى تسجيل تغيرات السكر في الدم لمعرفة العلاقة مع النظام الغذائي.</p><p>المنتج بعد إعادة الهيكلة يسمى &quot;كل بأمان يا صديق السكري&quot;، ويتموضع كـ &quot;مساعد سلامة غذائية&quot; لمرضى السكري.</p><hr><h4 id="المثال-الثاني-من-مساعد-الأخبار-إلى-ضابط-استخبارات-استثمارية" tabindex="-1">المثال الثاني: من &quot;مساعد الأخبار&quot; إلى &quot;ضابط استخبارات استثمارية&quot; <a class="header-anchor" href="#المثال-الثاني-من-مساعد-الأخبار-إلى-ضابط-استخبارات-استثمارية" aria-label="Permalink to “المثال الثاني: من &quot;مساعد الأخبار&quot; إلى &quot;ضابط استخبارات استثمارية&quot;”">​</a></h4><p>الفكرة العادية هي تجميع أخبار من منصات مختلفة لتوفير فتحها واحدة تلو الأخرى. لكن جينريتوتياو (Toutiao) وتينسنت نيوز وغيرها تقوم بذلك بشكل ممتاز بالفعل.</p><p>بعد التقسيم الأفقي، وجد شياو مينغ أن المحللين الماليين لديهم احتياجات خاصة: يحتاجون إلى تتبع ديناميكيات صناعات معينة، لكن المعلومات متفرقة جداً. وعند الحفر العمودي في سيناريوهاتهم: صباحاً يطلعون على ديناميكيات الأسهم الأمريكية overnight وتغيرات أسعار الصرف؛ قبل الظهر يتتبعون إعلانات الشركات في محفظتهم وأخبار الصناعة؛ بعد الظهر يبحثون في أهداف استثمارية محتملة ويحتاجون إلى معلومات صناعية كبيرة.</p><p>المنتج بعد إعادة الهيكلة يسمى &quot;ضابط الاستخبارات الاستثمارية&quot;، ويتموضع كـ &quot;رادار معلومات ومساعد قرار&quot; للممارسين الماليين.</p><hr><h4 id="المثال-الثالث-من-منصة-مستعملة-جامعية-إلى-مساعد-تصفية-التخرج" tabindex="-1">المثال الثالث: من &quot;منصة مستعملة جامعية&quot; إلى &quot;مساعد تصفية التخرج&quot; <a class="header-anchor" href="#المثال-الثالث-من-منصة-مستعملة-جامعية-إلى-مساعد-تصفية-التخرج" aria-label="Permalink to “المثال الثالث: من &quot;منصة مستعملة جامعية&quot; إلى &quot;مساعد تصفية التخرج&quot;”">​</a></h4><p>الفكرة العادية هي منصة تداول سلع مستعملة في الحرم الجامعي. لكن شيانيو (Xianyu) وزوانزوان (Zhuanzhuan) يقومان بذلك بشكل ممتاز بالفعل.</p><p>بعد التقسيم الأفقي، وجد شياو مينغ أن الخريجين لديهم احتياجات خاصة: الأشياء كثيرة جداً، وبيعها واحداً تلو الآخر مزعج. وعند الحفر العمودي في سيناريوهاتهم: قبل أسبوع من التخرج يجب مغادرة الحرم الجامعي، ولا يوجد وقت للبيع ببطء؛ لا يعرفون من يحتاج أشيائي؛ التفاوض والتسليم واستلام المال، كلها مرهقة.</p><p>المنتج بعد إعادة الهيكلة يسمى &quot;مساعد تصفية التخرج&quot;، ويتموضع كـ &quot;مدير أصول المغادرة&quot; للخريجين.</p><hr><h3 id="ملخص-هذا-الفصل-مكاسب-شياو-مينغ" tabindex="-1">ملخص هذا الفصل: مكاسب شياو مينغ <a class="header-anchor" href="#ملخص-هذا-الفصل-مكاسب-شياو-مينغ" aria-label="Permalink to “ملخص هذا الفصل: مكاسب شياو مينغ”">​</a></h3><p>من خلال الفصل الثاني، فهم شياو مينغ ما يلي:</p><p><strong>1. الانطلاق من النفس</strong></p><ul><li>أنت نفسك المستخدم، تفهم بشكل طبيعي نقاط ألم هذه المجموعة</li><li>الهواية هي أفضل نقطة بداية، والشغف هو أفضل محرك</li></ul><p><strong>2. التقسيم الأفقي للجمهور</strong></p><ul><li>لا تخدم &quot;الجميع&quot;، ابحث عن &quot;الفئة التي تعاني أكثر&quot;</li><li>كلما كان التقسيم أدق، زادت الفرص، وازداد استعداد المستخدمين للدفع</li></ul><p><strong>3. الحفر العمودي في السيناريوهات</strong></p><ul><li>صِف رحلة المستخدم الكاملة: قبل الاستخدام، أثناء الاستخدام، بعد الاستخدام</li><li>ابحث عن نقاط اللمس العاطفية: الخوف، القلق، العجز، الوحدة……</li></ul><p><strong>4. إعادة هيكلة القيمة</strong></p><ul><li>الترقية من &quot;وظيفة&quot; إلى &quot;حل&quot;</li><li>الترقية من &quot;أداة&quot; إلى &quot;مساعد/مدير/شريك&quot;</li></ul><hr><p>📦 <strong>مخرجات هذا الفصل:</strong></p><ul><li>العثور على مستخدمين مستهدفين دقيقين (الأمهات بعد الولادة)</li><li>فهم السيناريوهات الكاملة للمستخدمين ومشاعرهم الحقيقية</li><li>إعادة هيكلة مفهوم المنتج، مع تموضع تفاضلي واضح</li></ul><hr><h2 id="الفصل-الثالث-صقل-الحوار-مع-الذكاء-الاصطناعي" tabindex="-1">الفصل الثالث: صقل الحوار مع الذكاء الاصطناعي <a class="header-anchor" href="#الفصل-الثالث-صقل-الحوار-مع-الذكاء-الاصطناعي" aria-label="Permalink to “الفصل الثالث: صقل الحوار مع الذكاء الاصطناعي”">​</a></h2><p>لدى شياو مينغ الآن اتجاه منتج واضح: مساعد تعافي الأمهات بعد الولادة. لكنه لا يزال لا يعرف كيف يفعل ذلك بالتحديد، من أين يبدأ، وما مدى صعوبة التنفيذ التقني.</p><p>قرر استخدام الذكاء الاصطناعي لمساعدته في صقل مفهوم المنتج، وتحويل الأفكار إلى خطة قابلة للتنفيذ.</p><h3 id="الجولة-الأولى-طرح-الفكرة-الأصلية" tabindex="-1">الجولة الأولى: طرح الفكرة الأصلية <a class="header-anchor" href="#الجولة-الأولى-طرح-الفكرة-الأصلية" aria-label="Permalink to “الجولة الأولى: طرح الفكرة الأصلية”">​</a></h3><p>أخبر شياو مينغ الذكاء الاصطناعي بفكرته: &quot;أريد إنشاء تطبيق مساعد تعافي للأمهات بعد الولادة، لمساعدة الأمهات على استعادة قوامهن. لكنني قلق بشأن صعوبة التنفيذ التقني، خاصة وظيفة تصحيح الحركات بالذكاء الاصطناعي، هل يمكنني القيام بذلك بمفردي؟&quot;</p><hr><h3 id="الجولة-الثانية-الذكاء-الاصطناعي-يساعد-في-تخطيط-mvp" tabindex="-1">الجولة الثانية: الذكاء الاصطناعي يساعد في تخطيط MVP <a class="header-anchor" href="#الجولة-الثانية-الذكاء-الاصطناعي-يساعد-في-تخطيط-mvp" aria-label="Permalink to “الجولة الثانية: الذكاء الاصطناعي يساعد في تخطيط MVP”">​</a></h3><p>رد الذكاء الاصطناعي: &quot;سؤال رائع! دعنا نقوم بتخطيط MVP (المنتج الأدنى القابل للتطبيق).&quot;</p><p>اقترح الذكاء الاصطناعي القيام بذلك على ثلاث مراحل. المرحلة الأولى هي 1-2 شهر، والهدف هو التحقق من الطلب. عدم إنشاء تطبيق، بل البدء ببرنامج صغير على WeChat، يوفر فقط دورات مخصصة لما بعد الولادة (فيديو) ومجتمع تسجيل الحضور. استخدام الطريقة اليدوية لتقديم إرشادات الحركات، حيث يقوم المستخدمون برفع مقاطع الفيديو ويرد المدرب. الهدف هو التحقق مما إذا كانت الأمهات بعد الولادة مستعدات للدفع.</p><p>المرحلة الثانية هي 3-6 أشهر، إذا نجح التحقق في المرحلة الأولى، تتم إضافة الوظائف الأساسية. تطوير تصحيح الحركات بالذكاء الاصطناعي، يمكن استخدام SDK جاهز، مثل التعرف على جسم الإنسان من بايدو. إضافة خطط مخصصة، وتحسين وظائف المجتمع.</p><p>المرحلة الثالثة هي 6-12 شهراً، التوسع. تطوير تطبيق مستقل، والتعاون مع مؤسسات إعادة التأهيل بعد الولادة، والتوسع لتشمل فترة الحمل وما قبل الحمل.</p><p>بخصوص التنفيذ التقني، اقترح الذكاء الاصطناعي استخدام قدرات الذكاء الاصطناعي الجاهزة لتصحيح الحركات، مثل واجهات برمجة التطبيقات (API) من بايدو وتينسنت، دون الحاجة إلى التطوير من الصفر، مما يقلل التكاليف. في المرحلة المبكرة استخدام نموذج هجين يدوي مع الذكاء الاصطناعي، والانتقال تدريجياً.</p><p>بالنسبة لتكاليف البدء، تطوير البرنامج الصغير 10-20 ألف يوان (عبر الاستعانة بمصادر خارجية) أو القيام بذلك بنفسه باستخدام AI IDE، وإنتاج المحتوى من خلال التعاون مع مدربي إعادة التأهيل بعد الولادة، والبدء بالترويج من مجموعات الأمهات و Xiaohongshu.</p><p>مؤشرات التحقق هي 100 مستخدم في الشهر الأول، بمعدل تحويل مدفوع 10%. إذا تم تحقيق ذلك، فهذا يعني أن الطلب حقيقي، ويجب الاستمرار في الاستثمار؛ وإذا لم يتم تحقيق ذلك، يجب تعديل الاتجاه في الوقت المناسب.</p><hr><h3 id="الجولة-الثالثة-شياو-مينغ-يعبر-عن-مخاوفه" tabindex="-1">الجولة الثالثة: شياو مينغ يعبر عن مخاوفه <a class="header-anchor" href="#الجولة-الثالثة-شياو-مينغ-يعبر-عن-مخاوفه" aria-label="Permalink to “الجولة الثالثة: شياو مينغ يعبر عن مخاوفه”">​</a></h3><p>فكر شياو مينغ وسأل مرة أخرى: &quot;أنا قلق بشأن إنتاج المحتوى. دورات إعادة التأهيل بعد الولادة تحتاج إلى إرشاد احترافي، وليس لدي خلفية طبية، كيف أضمن جودة الدورات؟&quot;</p><hr><h3 id="الجولة-الرابعة-الذكاء-الاصطناعي-يقدم-حلاً" tabindex="-1">الجولة الرابعة: الذكاء الاصطناعي يقدم حلاً <a class="header-anchor" href="#الجولة-الرابعة-الذكاء-الاصطناعي-يقدم-حلاً" aria-label="Permalink to “الجولة الرابعة: الذكاء الاصطناعي يقدم حلاً”">​</a></h3><p>رد الذكاء الاصطناعي: &quot;هذا مخاوف العديد من رواد الأعمال التقنيين، لكن هناك حلاً.&quot;</p><p>الحل الأول هو التعاون مع محترفين. ابحث عن مدربي إعادة التأهيل بعد الولادة وأطباء التغذية في المستشفيات للتعاون، حيث تقدم أنت التكنولوجيا والمنتج، ويقدمون المحتوى الاحترافي، ويمكن استخدام نموذج تقاسم الإيرادات.</p><p>الحل الثاني هو دمج المحتوى عالي الجودة الموجود. في البداية يمكن استخدام مقاطع فيديو إعادة التأهيل بعد الولادة المتاحة للعامة، مثل تلك الموجودة على YouTube وBilibili. القيام بمراجعة وتنظيم المحتوى بنفسك، ثم إنتاج محتوى أصلي لاحقاً.</p><p>الحل الثالث هو المحتوى الذي ينشئه المستخدمون. تشجيع الأمهات ذوات الخبرة على مشاركة طرق التعافي الخاصة بهن، واستخدام تصويت المجتمع لفرز المحتوى عالي الجودة، وبناء نظام بيئي للمحتوى تدريجياً.</p><p>اقترح الذكاء الاصطناعي استخدام الحل الأول أولاً. الخطوات المحددة هي: العثور على 2-3 مدربين لإعادة التأهيل بعد الولادة، والتفاوض معهم على التعاون، حيث تقوم بتطوير المنتج ويوفرون الدورات. تقاسم الإيرادات بنسبة 70% لك و30% لهم. هذا يضمن جودة المحتوى ويقلل التكاليف في نفس الوقت. تكلفة إنتاج الدورات في المرحلة المبكرة 0 يوان، باستخدام نموذج تقاسم الإيرادات، تحتاج فقط لاستثمار وقت التطوير وتكاليف الترويج.</p><p><strong>نصيحتي: استخدم الحل الأول أولاً</strong></p><p>الخطوات المحددة:</p><ol><li>ابحث عن 2-3 مدربين لإعادة التأهيل بعد الولادة</li><li>التفاوض معهم على التعاون: أنت تطور المنتج، وهم يوفرون الدورات</li><li>تقاسم الإيرادات: أنت تأخذ 70%، وهم يأخذون 30%</li><li>هذا يضمن جودة المحتوى ويقلل التكاليف في نفس الوقت</li></ol><p><strong>التكاليف المبكرة:</strong></p><ul><li>إنتاج الدورات: 0 يوان (باستخدام نموذج تقاسم الإيرادات)</li><li>تحتاج فقط لاستثمار وقت التطوير وتكاليف الترويج</li></ul><p>:::</p><hr><h3 id="الجولة-الخامسة-شياو-مينغ-يسأل-عن-الترويج" tabindex="-1">الجولة الخامسة: شياو مينغ يسأل عن الترويج <a class="header-anchor" href="#الجولة-الخامسة-شياو-مينغ-يسأل-عن-الترويج" aria-label="Permalink to “الجولة الخامسة: شياو مينغ يسأل عن الترويج”">​</a></h3><p>كان لدى شياو مينغ قلق أخير: &quot;هل ستكون تكاليف الترويج مرتفعة؟ كيف أجد فئة الأمهات بعد الولادة؟&quot;</p><hr><h3 id="الجولة-السادسة-ai-يقدم-استراتيجية-ترويجية" tabindex="-1">الجولة السادسة: AI يقدم استراتيجية ترويجية <a class="header-anchor" href="#الجولة-السادسة-ai-يقدم-استراتيجية-ترويجية" aria-label="Permalink to “الجولة السادسة: AI يقدم استراتيجية ترويجية”">​</a></h3><p>ردّ AI قائلاً: &quot;مجموعة الأمهات بعد الولادة في الواقع سهلة العثور عليها، ويمكن أن تكون تكلفة الترويج منخفضة جداً.&quot;</p><p>الأكثر توصية هو Xiaohongshu. ابحث عن كلمات مفتاحية مثل &quot;تعافي ما بعد الولادة&quot;، &quot;انفصال العضلة المستقيمة&quot;، وابحث عن المدونين ذوي الصلة، وتواصل معهم عبر رسائل خاصة للتعاون. استخدم طريقة &quot;تجربة مجانية لمدة شهر واحد&quot; مقابل الترويج، التكلفة تكاد تكون 0.</p><p>ثانياً، مجموعات الأمهات. ابحث عن مجموعات WeChat ومجموعات QQ، وادخلها تحت مسمى &quot;مشاركة تجارب التعافي بعد الولادة&quot;، وشارك محتوى ذا قيمة حقيقية، دون إعلانات مباشرة، لبناء الثقة تدريجياً.</p><p>يمكنك أيضاً التعاون مع أقسام الولادة في المستشفيات، وتقديم إرشادات مجانية للتعافي بعد الولادة، وتوزيع منشورات في المستشفى، التكلفة هي مجرد رسوم طباعة بضع مئات من اليوان. أو التعاون مع متاجر الأمومة والطفولة، ووضع مواد ترويجية، وشراء منتجات الأمومة والطفولة مع بطاقات تجريبية مجانية، التكلفة هي فقط رسوم إنتاج البطاقات التجريبية.</p><p>مؤشرات التحقق هي: 100 مستخدم في الشهر الأول، 10 مستخدمين مدفوعين (معدل تحويل 10%)، إجمالي تكلفة الترويج أقل من 1000 يوان، وتكلفة الاستحواذ على العميل أقل من 10 يوان لكل شخص. إذا تم تحقيق هذا المؤشر، فهذا يعني أن الطلب حقيقي ويمكن الاستمرار في الاستثمار.</p><hr><h3 id="النهاية-أصبح-لدى-شياو-مينغ-خطة-واضحة" tabindex="-1">النهاية: أصبح لدى شياو مينغ خطة واضحة <a class="header-anchor" href="#النهاية-أصبح-لدى-شياو-مينغ-خطة-واضحة" aria-label="Permalink to “النهاية: أصبح لدى شياو مينغ خطة واضحة”">​</a></h3><p>بعد 6 جولات من المحادثة، أصبح لدى شياو مينغ أخيراً خطة واضحة.</p><p>المرحلة الأولى هي 1-2 شهر: إنشاء تطبيق WeChat Mini Program، والتعاون مع 2-3 مدربي إعادة تأهيل ما بعد الولادة (نموذج تقاسم الأرباح)، وتقديم دورات حصرية لما بعد الولادة (فيديو) ومجتمع تسجيل الوصول فقط، واستخدام الطريقة اليدوية لتقديم إرشادات الحركة. الهدف هو 100 مستخدم، ومعدل تحويل مدفوع 10%.</p><p>المرحلة الثانية هي 3-6 أشهر: إذا تم التحقق من نجاح المرحلة الأولى، استمر في الاستثمار. أضف وظيفة تصحيح الحركة بالـ AI، وزد الخطط المخصصة، وحسّن وظائف المجتمع.</p><p>المرحلة الثالثة هي 6-12 شهرًا: تطوير تطبيق مستقل، والتعاون مع مؤسسات إعادة تأهيل ما بعد الولادة، والتوسع لتشمل فترة الحمل وفترة الاستعداد للحمل.</p><p>تكلفة البدء منخفضة جدًا: التطوير يتم باستخدام AI IDE بنفسه (0 يوان)، المحتوى بتقاسم الأرباح مع المدربين (0 يوان مسبقًا)، الترويج عبر Xiaohongshu ومجموعات الأمهات (أقل من 1000 يوان). التكلفة الإجمالية أقل من 1000 يوان.</p><hr><h3 id="طريقة-الخطوات-الخمس-لصقل-محادثة-ai" tabindex="-1">طريقة الخطوات الخمس لصقل محادثة AI <a class="header-anchor" href="#طريقة-الخطوات-الخمس-لصقل-محادثة-ai" aria-label="Permalink to “طريقة الخطوات الخمس لصقل محادثة AI”">​</a></h3><p>من خلال هذه الحالة، لخص شياو مينغ عملية قياسية للحوار مع AI (للمحتوى التفصيلي، راجع الملحق E).</p><p><strong>الخطوة الأولى: اطرح فكرتك الأصلية.</strong> صِف فكرتك الأولية، حتى لو كانت خامًا، لا بأس بذلك. أخبر AI بمخاوفك، مثل المنافسة الشديدة، أو عدم معرفة كيفية التمايز وغيرها.</p><p><strong>الخطوة الثانية: دع AI يساعدك في تخطيط MVP.</strong> ما هي الوظائف التي يجب أن يتضمنها الحد الأدنى من المنتج القابل للتطبيق؟ كم عدد المراحل؟ ما هو هدف كل مرحلة؟ هل صعوبة التنفيذ التقني كبيرة؟</p><p><strong>الخطوة الثالثة: اطرح مخاوفك.</strong> صعوبة التنفيذ التقني؟ تكلفة إنتاج المحتوى؟ تكلفة الترويج؟ صعوبة الاستحواذ على المستخدمين؟ أخبر AI بجميع مخاوفك.</p><p><strong>الخطوة الرابعة: دع AI يقدم حلولاً.</strong> بناءً على مخاوفك، سيقدم AI اقتراحات محددة. مقارنة بين حلول متعددة، واختيار الأمثل. تقدير التكلفة.</p><p><strong>الخطوة الخامسة: التأكيد النهائي على الخطة.</strong> قم بتنظيم خطة عمل واضحة، وحدد مؤشرات التحقق. إذا لم يتم تحقيقها، قم بتعديل الاتجاه في الوقت المناسب.</p><p><strong>قالب الأوامر (Prompt):</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد أن أصنع [مفهوم المنتج]،</span></span>
<span class="line"><span>لكنني قلق بشأن [مخاوفك].</span></span>
<span class="line"><span>ساعدني في:</span></span>
<span class="line"><span>1. تخطيط MVP (المنتج الأدنى المقبول)</span></span>
<span class="line"><span>2. تقديم اقتراحات محددة للتنفيذ التقني</span></span>
<span class="line"><span>3. تقدير التكاليف</span></span>
<span class="line"><span>4. تحديد مؤشرات التحقق</span></span></code></pre></div><hr><h3 id="ملخص-هذا-الفصل-مكاسب-شياو-مينغ-1" tabindex="-1">ملخص هذا الفصل: مكاسب شياو مينغ <a class="header-anchor" href="#ملخص-هذا-الفصل-مكاسب-شياو-مينغ-1" aria-label="Permalink to “ملخص هذا الفصل: مكاسب شياو مينغ”">​</a></h3><p>من خلال الفصل الثالث، فهم شياو مينغ ثلاثة أشياء.</p><p><strong>أولاً، استخدام محادثة AI لصقل مفهوم المنتج.</strong> لا تتوقع الحصول على إجابة مثالية من محادثة واحدة، بل قم بتكرارات متعددة. أخبر AI بملاحظاتك وتجاربك وردود الفعل من الأشخاص من حولك. إذا كانت اقتراحات AI غير معقولة، أشر إلى ذلك في الوقت المناسب. في النهاية، يجب أن تصل إلى خطة عمل محددة.</p><p><strong>ثانياً، المبدأ الأساسي لـ MVP.</strong> التقليل إلى الحد الأدنى، والقيام فقط بالوظائف الأساسية. قابل للتحقق، والقدرة على التحقق بسرعة مما إذا كان الطلب حقيقيًا. تكلفة منخفضة، والتحقق بأقل تكلفة ممكنة.</p><p><strong>ثالثاً، مؤشرات التحقق.</strong> إذا كان معدل التحويل المدفوع أكبر من 10%، فهذا يعني أن الطلب حقيقي ويستحق الاستثمار. إذا كان معدل التحويل المدفوع 5-10%، فهذا يعني أن الطلب موجود ولكنه يحتاج إلى صقل. إذا كان معدل التحويل المدفوع أقل من 5%، فهذا يعني أن الطلب غير صالح، ويجب تعديله في الوقت المناسب.</p><hr><p>📦 <strong>مخرجات هذا الفصل:</strong></p><ul><li>أصبح لديك خطة MVP واضحة</li><li>عرفت مسار التنفيذ التقني</li><li>حددت مؤشرات التحقق</li></ul><hr><h2 id="الفصل-الأخير-خطوتك-القادمة" tabindex="-1">الفصل الأخير: خطوتك القادمة <a class="header-anchor" href="#الفصل-الأخير-خطوتك-القادمة" aria-label="Permalink to “الفصل الأخير: خطوتك القادمة”">​</a></h2><h3 id="قاعدة-حفظ" tabindex="-1">قاعدة حفظ <a class="header-anchor" href="#قاعدة-حفظ" aria-label="Permalink to “قاعدة حفظ”">​</a></h3><p><strong>شخص واحد، أمر واحد، نقطة دخول واحدة، تقطيع أفقي وحفر عمودي لإيجاد نقاط الألم، حوار AI لصقل المفهوم، التحقق بخمس خطوات قبل البدء</strong></p><p><strong>الشرح:</strong></p><ul><li><strong>شخص واحد:</strong> ابدأ بنفسك، فأنت تفهم هذه المجموعة بشكل طبيعي</li><li><strong>أمر واحد:</strong> ركّز على شيء واحد محدد، لا تطمع في الكثير</li><li><strong>نقطة دخول واحدة:</strong> ابحث عن نقطة الدخول، وكلما كانت أدق كان ذلك أفضل</li><li><strong>التقطيع الأفقي:</strong> قسّم الجمهور أفقيًا للعثور على المستخدمين الأكثر استعدادًا للدفع</li><li><strong>الحفر العمودي:</strong> احفر عموديًا في السيناريوهات لفهم الرحلة الكاملة للمستخدم</li><li><strong>حوار AI:</strong> استخدم محادثة AI لصقل مفهوم المنتج</li><li><strong>التحقق بخمس خطوات:</strong> استخدم طريقة الحكم بخمس خطوات للتحقق من صحة الطلب</li></ul><hr><h3 id="تمرين-بعد-الفصل" tabindex="-1">تمرين بعد الفصل <a class="header-anchor" href="#تمرين-بعد-الفصل" aria-label="Permalink to “تمرين بعد الفصل”">​</a></h3><p>اختر مشكلة صغيرة تواجهها في حياتك اليومية، وقم بتوسيعها باستخدام طريقة هذا الفصل:</p><div class="tip custom-block"><p class="custom-block-title">مهمة التمرين</p><p><strong>1. صِف هذه المشكلة</strong> (بجملة واحدة)</p><ul><li>مثال: &quot;أريد إنشاء تطبيق لتتبع المصاريف، يساعد المستخدمين على تسجيل نفقاتهم&quot;</li></ul><p><strong>2. التقطيع الأفقي: ابحث عن 3 مجموعات قد تكون لديها احتياجات مختلفة</strong></p><ul><li>مثال: أصحاب الأعمال الصغيرة والمتوسطة، آباء الطلاب الدوليين، العاملون المستقلون</li></ul><p><strong>3. اختر إحدى المجموعات، وقم بالحفر العمودي: صِف سيناريوهاتهم الكاملة ومشاعرهم الحقيقية</strong></p><ul><li>مثال: سيناريو آباء الطلاب الدوليين — يريدون معرفة كم أنفق أبناؤهم في الخارج، لكن الأبناء لا يقولون</li></ul><p><strong>4. إعادة بناء مفهوم المنتج: التطور من &quot;وظيفة واحدة&quot; إلى &quot;حل متكامل&quot;</strong></p><ul><li>مثال: &quot;مدير أموال الطلاب الدوليين&quot; — ليس مجرد تسجيل مصاريف، بل جعل الآباء &quot;على دراية&quot; بنفقات أبنائهم في الخارج</li></ul><p><strong>5. استخدم قائمة التحقق لتقييم فكرتك</strong> (انظر الملحق F)</p><p><strong>شارك تحليلك في المجتمع وناقشه مع المتدربين الآخرين!</strong></p></div><hr><h2 id="الملحق-منهجية-sop" tabindex="-1">الملحق: منهجية SOP <a class="header-anchor" href="#الملحق-منهجية-sop" aria-label="Permalink to “الملحق: منهجية SOP”">​</a></h2><h3 id="الملحق-أ-طريقة-الحكم-بخمس-خطوات-لتحليل-الاحتياجات" tabindex="-1">الملحق أ: طريقة الحكم بخمس خطوات لتحليل الاحتياجات <a class="header-anchor" href="#الملحق-أ-طريقة-الحكم-بخمس-خطوات-لتحليل-الاحتياجات" aria-label="Permalink to “الملحق أ: طريقة الحكم بخمس خطوات لتحليل الاحتياجات”">​</a></h3><p>عندما يكون لديك فكرة، كيف تحكم بسرعة على ما إذا كانت تستحق الاستثمار؟</p><p><strong>الخطوة الأولى: التحقق من المستخدم — ابحث عن 10 مستخدمين مستهدفين</strong></p><p><strong>لا تسأل:</strong> &quot;هل ستستخدم منتجي؟&quot; (معدل إيجابية كاذبة 90%)</p><p><strong>اسأل:</strong></p><ol><li>&quot;كيف تحل هذه المشكلة حاليًا؟&quot; (فهم السلوك الحقيقي)</li><li>&quot;خلال الأسبوع الماضي، كم مرة أزعجتك هذه المشكلة؟&quot; (فهم التكرار)</li><li>&quot;كم من المال/الوقت أنفقت لحلها؟&quot; (فهم الاستعداد للدفع)</li><li>&quot;إذا كان هناك حل، لكنه يتطلب تغيير العادات، هل ستوافق؟&quot; (فهم تكلفة التغيير)</li></ol><p><strong>معايير الحكم:</strong></p><ul><li>إذا قال أكثر من 3 مستخدمين &quot;أعاني من هذه المشكلة كل يوم&quot; — قد تكون نقطة ألم</li><li>إذا قال المستخدم &quot;إنها مثيرة للاهتمام، لكنني لست في عجلة من أمري&quot; — من المحتمل جدًا أنها مجرد رغبة</li><li>إذا قال المستخدم &quot;أستخدم حاليًا XX للحل، لكنني لست راضيًا تمامًا&quot; — هناك فرصة</li></ul><p><strong>السؤال الرئيسي:</strong> ما هي الطريقة التي يستخدمها المستخدمون حاليًا لحل هذه المشكلة؟</p><table tabindex="0"><thead><tr><th>نوع البديل</th><th>الشرح</th><th>الحكم على الفرصة</th></tr></thead><tbody><tr><td><strong>لا يوجد بديل</strong></td><td>المستخدم يتحمل بصمت</td><td>فرصة كبيرة، لكنها تتطلب تثقيف السوق</td></tr><tr><td><strong>استخدام طريقة بدائية</strong></td><td>Excel، العمل اليدوي، تعاون عدة أشخاص</td><td>فرصة جيدة، المستخدمون يتوقون لحل أفضل</td></tr><tr><td><strong>استخدام عدة أدوات معًا</strong></td><td>أداة A + أداة B + أداة C</td><td>فرصة جيدة، الدمج له قيمة</td></tr><tr><td><strong>استخدام منتج ناضج</strong></td><td>لكن المستخدم غير راضٍ</td><td>هناك فرصة، لكنها تتطلب التمايز</td></tr><tr><td><strong>استخدام منتج ناضج</strong></td><td>المستخدم راضٍ جدًا</td><td>الفرصة ضئيلة، ما لم يكن هناك ابتكار تخريبي</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">ما هو &quot;الابتكار التخريبي&quot;؟</p><p><strong>تعريف بسيط:</strong> لا يتعل الأمر بجعل المنتج أفضل فحسب، بل بخدمة مجموعات المستخدمين التي تم تجاهلها سابقًا بطريقة أبسط/أرخص.</p><p><strong>أمثلة:</strong></p><ul><li>الهواتف التقليدية ← الهواتف الذكية (ليس هناك المزيد من الوظائف، بل طريقة تفاعل مختلفة تمامًا)</li><li>سيارات الأجرة التقليدية ← DiDi (ليست سيارة أفضل، بل جعل استدعاء السيارة متاحًا في أي وقت وفي أي مكان)</li><li>المكتبات التقليدية ← الكتب الإلكترونية (ليس هناك المزيد من الكتب، بل جعل الحمل والشراء أكثر ملاءمة)</li></ul><p><strong>النقطة الأساسية:</strong> يبدأ الابتكار التخريبي غالبًا من &quot;السوق المنخفضة&quot; أو &quot;مجموعات المستخدمين الجدد&quot;، ويتقدم تدريجيًا نحو الأعلى.</p></div><p><strong>حالات دراسية:</strong></p><ul><li>مرضى السكري يستخدمون حاليًا &quot;الخبرة + التخمين&quot; للتحكم في النظام الغذائي (طريقة بدائية للغاية) — فرصة كبيرة</li><li>الأشخاص العاديون الذين يتبعون حمية يستخدمون تطبيق Bohe Health (منتج ناضج، مستوى الرضا متوسط) — هناك فرصة للقيام بالتخصص الدقيق</li><li>الطلاب يستخدمون مجموعات WeChat للمعاملات المستعملة (عدة أدوات معًا) — هناك فرصة للقيام بالدمج</li></ul><p><strong>الطريقة الأكثر فعالية: البيع المسبق أو الدفع المقدم</strong></p><p><strong>خطوات التشغيل:</strong></p><ol><li>أنشئ صفحة هبوط بسيطة تصف مفهوم منتجك</li><li>ضع زر &quot;بيع مسبق&quot; أو &quot;حجز&quot;</li><li>انظر كم عدد الأشخاص المستعدين للدفع (حتى لو كان يوانًا واحدًا فقط)</li></ol><p><strong>معايير الحكم:</strong></p><ul><li>المستخدمون المستعدون لدفع مقدمًا &gt; 10%: الطلب حقيقي، يستحق التنفيذ</li><li>المستخدمون المستعدون لدفع مقدمًا 5-10%: الطلب موجود، لكنه يحتاج إلى صقل</li><li>المستخدمون المستعدون لدفع مقدمًا &lt; 5%: الطلب غير صالح، أو أن مفهوم المنتج به مشكلة</li></ul><p><strong>ملاحظة:</strong> الكثير من الأشخاص يقولون &quot;سأشتري&quot;، لكن من يدفعون فعليًا هم عملاؤك المستهدفون.</p><p><strong>صيغة بسيطة:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>حجم السوق المحتمل = عدد المستخدمين المستهدفين × الاستعداد للدفع × متوسط قيمة الطلب</span></span></code></pre></div><p><strong>حالة دراسية: منصة تداول سلع مستعملة داخل الحرم الجامعي</strong></p><ul><li>المستخدمون المستهدفون: طلاب الجامعات على مستوى البلاد 40 مليون</li><li>من لديهم طلب على تداول السلع المستعملة: 50% = 20 مليون</li><li>المستعدون لاستخدام المنصة: 10% = 2 مليون</li><li>تكرار المعاملات السنوي: مرتان</li><li>عمولة المنصة: 5%</li><li>متوسط قيمة الطلب: 100 يوان</li><li>حجم السوق المحتمل = 2 مليون × 2 × 100 × 5% = 20 مليون/سنة</li></ul><p><strong>معايير الحكم:</strong></p><ul><li>حجم السوق &gt; 1 مليار: مسار كبير، يستحق العمل عليه</li><li>حجم السوق 1-10 مليون: مسار صغير ومتوسط، يمكن العمل فيه ولكن السقف واضح</li><li>حجم السوق &lt; 1 مليون: سوق متخصصة، مناسبة كعمل جانبي أو مشروع صغير وجميل</li></ul><p><strong>سؤال جوهري:</strong> إذا نجح المنتج، ماذا تفعل حيال نسخه من قبل الآخرين؟</p><p><strong>أنواع الخنادق الدفاعية الشائعة:</strong></p><table tabindex="0"><thead><tr><th>نوع الخندق الدفاعي</th><th>الشرح</th><th>المثال</th></tr></thead><tbody><tr><td><strong>تأثير الشبكة</strong></td><td>كلما زاد المستخدمون، زادت قيمة المنتج</td><td>WeChat، DiDi</td></tr><tr><td><strong>تراكم البيانات</strong></td><td>كلما زادت البيانات، أصبحت الخوارزميات أكثر دقة</td><td>Toutiao، Douyin</td></tr><tr><td><strong>الوعي بالعلامة التجارية</strong></td><td>احتلال عقل المستخدم</td><td>Coca-Cola، Nike</td></tr><tr><td><strong>تأثير الحجم</strong></td><td>كلما زاد الحجم، انخفضت التكلفة</td><td>JD Logistics، Amazon</td></tr><tr><td><strong>براءات الاختراع التقنية</strong></td><td>حواجز التكنولوجيا الأساسية</td><td>Huawei، DJI</td></tr><tr><td><strong>تكلفة التحويل</strong></td><td>تكلفة انتقال المستخدم عالية</td><td>برمجيات المؤسسات، أنظمة التشغيل</td></tr></tbody></table><p><strong>واقع المشاريع المبكرة:</strong></p><ul><li>معظم المشاريع المبكرة ليس لديها خنادق دفاعية واضحة</li><li>لكن هذا لا يهم، الأهم هو <strong>التحرك بسرعة</strong></li><li>احتل السوق أولاً، ثم ابنِ الحواجز</li></ul><hr><h3 id="الملحق-ب-طريقة-التقسيم-الأفقي-للجمهور" tabindex="-1">الملحق ب: طريقة التقسيم الأفقي للجمهور <a class="header-anchor" href="#الملحق-ب-طريقة-التقسيم-الأفقي-للجمهور" aria-label="Permalink to “الملحق ب: طريقة التقسيم الأفقي للجمهور”">​</a></h3><p>لا تحاول خدمة &quot;جميع مستخدمي XX&quot;، بل ابحث عن <strong>مجموعة محددة من الأشخاص</strong> تكون احتياجاتهم أكثر إلحاحًا وتحديدًا.</p><p><strong>الخطوة الأولى: اذكر جميع الفئات الممكنة</strong></p><p>بالنسبة لمفهوم منتجك، اذكر جميع الفئات الممكنة.</p><p><strong>الخطوة الثانية: تقييم القيمة التجارية لكل فئة</strong></p><table tabindex="0"><thead><tr><th>بُعد التقييم</th><th>الشرح</th></tr></thead><tbody><tr><td>قوة نقطة الألم</td><td>هل احتياج هذه الفئة هو نقطة ألم أم مجرد رغبة؟</td></tr><tr><td>الاستعداد للدفع</td><td>كم يرغبون في الدفع مقابل الحل؟</td></tr><tr><td>حجم السوق</td><td>كم عدد الأشخاص في هذه الفئة؟</td></tr><tr><td>مستوى المنافسة</td><td>هل الحلول الحالية مُرضية؟</td></tr><tr><td>فهمك للفئة</td><td>هل تفهم هذه الفئة؟ هل لديك قنوات للوصول إليها؟</td></tr></tbody></table><p><strong>الخطوة الثالثة: اختر فئة واحدة للتحليل المتعمق</strong></p><p>اختر فئة:</p><ul><li>تعاني من أشد نقاط الألم</li><li>لديها أقوى استعداد للدفع</li><li>تفهمها أفضل ما يمكن</li><li>ذات منافسة منخفضة نسبيًا</li></ul><div class="tip custom-block"><p class="custom-block-title">مثال على التقسيم</p><p><strong>مفهوم المنتج:</strong> تطبيق لتتبع المصاريف</p><table tabindex="0"><thead><tr><th>الفئة المحددة</th><th>نقطة الألم</th><th>الاستعداد للدفع</th><th>حجم السوق</th><th>مستوى المنافسة</th></tr></thead><tbody><tr><td>موظفو المكاتب العاديون</td><td>متاعب في التسجيل</td><td>منخفض</td><td>كبير</td><td>عالي</td></tr><tr><td>أصحاب الأعمال الصغيرة والمتوسطة</td><td>خلط بين النفقات الشخصية والشركات</td><td>عالي</td><td>متوسط</td><td>متوسط</td></tr><tr><td>المستقلون</td><td>دخل غير مستقر، الحاجة للتنبؤ بالتدفق النقدي</td><td>عالي</td><td>متوسط</td><td>متوسط</td></tr><tr><td>آباء الطلاب المغتربين</td><td>يريدون معرفة كم ينفق أبناؤهم، لكن الأبناء لا يخبرونهم</td><td>عالي</td><td>صغير</td><td>منخفض</td></tr></tbody></table><p><strong>الاختيار:</strong> آباء الطلاب المغتربين (نقطة الألم الأقوى، استعداد عالي للدفع، منافسة منخفضة نسبيًا)</p></div><hr><h3 id="الملحق-ج-طريقة-الحفر-العمودي-للاكتشاف" tabindex="-1">الملحق ج: طريقة الحفر العمودي للاكتشاف <a class="header-anchor" href="#الملحق-ج-طريقة-الحفر-العمودي-للاكتشاف" aria-label="Permalink to “الملحق ج: طريقة الحفر العمودي للاكتشاف”">​</a></h3><p>بعد العثور على الفئة المستهدفة، لا تتوقف عند ميزة واحدة، بل يجب أن تفهم <strong>السيناريو الكامل</strong> للمستخدم.</p><p><strong>الخطوة الأولى: صف يوم المستخدم</strong></p><p>من الصباح إلى المساء، صِف السيناريو الكامل للمستخدم عند استخدامه لمنتجك.</p><p><strong>الخطوة الثانية: حلل نقاط الألم في كل سيناريو</strong></p><p>في كل سيناريو، ما هي المشاكل التي يواجهها المستخدم؟ وما هي مشاعره؟</p><p><strong>الخطوة الثالثة: ابحث عن المحفزات العاطفية</strong></p><p>الخوف، القلق، العجز، الوحدة، الغضب، الندم……</p><p><strong>الخطوة الرابعة: إعادة بناء القيمة</strong></p><p>بناءً على السيناريو والمشاعر، أعد بناء قيمة المنتج.</p><div class="tip custom-block"><p class="custom-block-title">مثال على الحفر العميق</p><p><strong>الفئة:</strong> الأمهات الجدد</p><table tabindex="0"><thead><tr><th>الوقت</th><th>السيناريو</th><th>نقطة الألم</th><th>المشاعر</th></tr></thead><tbody><tr><td>6 صباحًا</td><td>الطفل نام للتو، لديها 30 دقيقة فراغ</td><td>لا تعرف أي تمارين آمنة للقيام بها</td><td>الخوف</td></tr><tr><td>10 صباحًا</td><td>تحمل الطفل لتنويمه، ألم شديد في الظهر</td><td>يداها مشغولتان، تريد القيام بتمارين التعافي</td><td>القلق</td></tr><tr><td>3 مساءً</td><td>الطفل نائم، تريد ممارسة الرياضة</td><td>الجسد متعب جدًا، لا تدري إن كانت قادرة</td><td>العجز</td></tr><tr><td>8 مساءً</td><td>أخيرًا لديها وقت فراغ</td><td>تنظر في المرآة وتشعر أن حياتها انتهت</td><td>الاكتئاب</td></tr><tr><td>على المدى الطويل</td><td>لا أحد يفهمها</td><td>تشعر أنها الوحيدة التي تعاني هكذا</td><td>الوحدة</td></tr></tbody></table><p><strong>إعادة بناء القيمة:</strong> الترقية من &quot;أداة لياقة&quot; إلى &quot;مدرب تعافي + داعم نفسي&quot;</p></div><hr><h3 id="الملحق-د-المزيد-من-الأمثلة-لتحويل-الفكرة-العادية-إلى-فكرة-ممتازة" tabindex="-1">الملحق د: المزيد من الأمثلة لتحويل الفكرة العادية إلى فكرة ممتازة <a class="header-anchor" href="#الملحق-د-المزيد-من-الأمثلة-لتحويل-الفكرة-العادية-إلى-فكرة-ممتازة" aria-label="Permalink to “الملحق د: المزيد من الأمثلة لتحويل الفكرة العادية إلى فكرة ممتازة”">​</a></h3><h4 id="المثال-الأول-من-تطبيق-تتبع-مصاريف-إلى-مدير-مالية-الدراسة-بالخارج" tabindex="-1">المثال الأول: من &quot;تطبيق تتبع مصاريف&quot; إلى &quot;مدير مالية الدراسة بالخارج&quot; <a class="header-anchor" href="#المثال-الأول-من-تطبيق-تتبع-مصاريف-إلى-مدير-مالية-الدراسة-بالخارج" aria-label="Permalink to “المثال الأول: من &quot;تطبيق تتبع مصاريف&quot; إلى &quot;مدير مالية الدراسة بالخارج&quot;”">​</a></h4><p><strong>الفكرة العادية:</strong> تطبيق تتبع مصاريف تلقائي، يتصل بالبطاقة البنكية ويصنف النفقات تلقائيًا</p><p><strong>المشكلة:</strong> السوق يحتوي بالفعل على SuiShouJi و Wacai وكشف حسابات Alipay……</p><p><strong>التقسيم الأفقي:</strong></p><ul><li>آباء الطلاب المغتربين: يريدون معرفة كم أنفق أبناؤهم في الخارج، وهل تجاوزوا الميزانية</li></ul><p><strong>الحفر العمودي:</strong></p><ul><li>نقطة الألم ليست &quot;تسجيل المصاريف&quot;، بل <strong>&quot;الشعور بفقدان السيطرة&quot;</strong>——لا يعرفون كم أنفق الطفل ولا أين أنفق</li><li>السيناريو: رؤية كشف حساب البطاقة الائتمانية كل شهر، لكن الطفل لا يخبرهم أبدًا بما أنفقه</li></ul><p><strong>بعد إعادة البناء:</strong> &quot;مدير مالية الدراسة بالخارج&quot;——ليس مجرد تسجيل مصاريف، بل جعل الآباء &quot;على دراية&quot; بنفقات أبنائهم في الخارج</p><p><strong>الميزات الأساسية:</strong></p><ul><li>مزامنة نفقات الأبناء في الوقت الفعلي</li><li>تنبيهات تجاوز الميزانية</li><li>تقرير تحليل النفقات الشهري</li><li>مقارنة النفقات مع الطلاب المماثلين (&quot;ابنك أنفق أكثر من المتوسط بنسبة 20%&quot;)</li></ul><hr><h4 id="المثال-الثاني-من-أداة-تقنية-البومودورو-إلى-إثبات-العمل-عن-بُعد" tabindex="-1">المثال الثاني: من &quot;أداة تقنية البومودورو&quot; إلى &quot;إثبات العمل عن بُعد&quot; <a class="header-anchor" href="#المثال-الثاني-من-أداة-تقنية-البومودورو-إلى-إثبات-العمل-عن-بُعد" aria-label="Permalink to “المثال الثاني: من &quot;أداة تقنية البومودورو&quot; إلى &quot;إثبات العمل عن بُعد&quot;”">​</a></h4><p><strong>الفكرة العادية:</strong> تطبيق تقنية البومودورو، يساعد المستخدمين على التركيز في العمل</p><p><strong>المشكلة:</strong> الهواتف تحتوي بالفعل على وقت استخدام الشاشة، و Forest، و Tomato Todo……</p><p><strong>التقسيم الأفقي:</strong></p><ul><li>العاملون عن بُعد: يحتاجون لإثبات للرئيس &quot;أنا أعمل بالفعل&quot;</li></ul><p><strong>الحفر العمودي:</strong></p><ul><li>نقطة الألم ليست &quot;عدم التركيز&quot;، بل <strong>&quot;أزمة ثقة&quot;</strong>——الرئيس لا يراني، كيف أثبت أنني أعمل؟</li><li>السيناريو: في نهاية كل يوم، يسأل الرئيس &quot;كيف كان العمل اليوم؟&quot;، لا توجد طريقة لإثبات ذلك</li></ul><p><strong>بعد إعادة البناء:</strong> &quot;إثبات العمل عن بُعد&quot;——مساعدة العاملين عن بُعد على بناء الثقة مع أصحاب العمل</p><p><strong>الميزات الأساسية:</strong></p><ul><li>تتبع تلقائي لساعات العمل</li><li>تقرير الإنتاجية</li><li>ملخص نشاط الشاشة (نسخة تحمي الخصوصية)</li><li>إنشاء &quot;تقرير عمل&quot; تلقائي يوميًا وإرساله للمدير</li></ul><hr><h4 id="المثال-الثالث-من-تجارة-الكتب-المستعملة-إلى-مكتبة-كتب-مصورة" tabindex="-1">المثال الثالث: من &quot;تجارة الكتب المستعملة&quot; إلى &quot;مكتبة كتب مصورة&quot; <a class="header-anchor" href="#المثال-الثالث-من-تجارة-الكتب-المستعملة-إلى-مكتبة-كتب-مصورة" aria-label="Permalink to “المثال الثالث: من &quot;تجارة الكتب المستعملة&quot; إلى &quot;مكتبة كتب مصورة&quot;”">​</a></h4><p><strong>الفكرة العادية:</strong> منصة لبيع الكتب المستعملة</p><p><strong>المشكلة:</strong> DuoZhuaYu، XianShu، Kongfz……</p><p><strong>التقسيم الأفقي:</strong></p><ul><li>الأمهات: كتب الأطفال المصورة تُقرأ مرة واحدة ثم تُترك، لكن شراء الجديدة مكلف للغاية</li></ul><p><strong>الحفر العمودي:</strong></p><ul><li>نقطة الألم ليست &quot;الكتب غالية&quot;، بل <strong>&quot;دورة حياة الكتب المصورة قصيرة&quot;</strong>——الكتب التي يقرأها الطفل في سن 3 سنوات، لن يقرأها في سن 4 سنوات</li><li>السيناريو: المنزل ممتلئ بالكتب المصورة التي لم يعد الطفل يقرأها، لكن التخلص منها أمر مؤسف</li></ul><p><strong>بعد إعادة البناء:</strong> &quot;مكتبة كتب مصورة تصل إلى باب منزلك&quot;——ليس بيع كتب مستعملة، بل توفير &quot;إيجار حق استخدام&quot; للكتب المصورة</p><p><strong>الميزات الأساسية:</strong></p><ul><li>اشتراك الكتب المصورة (إرسال 5 كتب مناسبة للعمر شهريًا، إرجاعها بعد قراءتها واستبدالها بأخرى جديدة)</li><li>تتبع تقدم القراءة</li><li>توصيات مناسبة للعمر</li><li>ضمان التعقيم</li></ul><hr><h3 id="الملحق-هـ-طريقة-الخطوات-الخمس-لصقل-مفهوم-المنتج-عبر-محادثات-الذكاء-الاصطناعي" tabindex="-1">الملحق هـ: طريقة الخطوات الخمس لصقل مفهوم المنتج عبر محادثات الذكاء الاصطناعي <a class="header-anchor" href="#الملحق-هـ-طريقة-الخطوات-الخمس-لصقل-مفهوم-المنتج-عبر-محادثات-الذكاء-الاصطناعي" aria-label="Permalink to “الملحق هـ: طريقة الخطوات الخمس لصقل مفهوم المنتج عبر محادثات الذكاء الاصطناعي”">​</a></h3><p>من خلال جولات متعددة من محادثات الذكاء الاصطناعي، يتم صقل الفكرة العادية تدريجيًا لتصبح مفهوم منتج دقيقًا وقابلًا للتنفيذ.</p><p><strong>الإجراء:</strong></p><ul><li>صِف فكرتك الأولية (حتى لو كانت أولية جدًا)</li><li>أخبر الذكاء الاصطناعي عن مخاوفك (منافسة شديدة، لا تعرف كيف تتميز، إلخ)</li></ul><p><strong>نص التلميح:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أريد إنشاء [مفهوم المنتج]،</span></span>
<span class="line"><span>لكنني اكتشفت [المشكلة/المخاوف].</span></span></code></pre></div><p><strong>الإجراء:</strong></p><ul><li>اطلب من الذكاء الاصطناعي مساعدتك في وضع خطة للحد الأدنى للمنتج القابل للتطبيق (MVP)</li><li>ناقش صعوبة وتكلفة التنفيذ التقني</li><li>حدد مؤشرات التحقق</li></ul><p><strong>نص التلميح:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>يرجى مساعدتي في:</span></span>
<span class="line"><span>1. تخطيط MVP</span></span>
<span class="line"><span>2. تقديم اقتراحات محددة للتنفيذ التقني</span></span>
<span class="line"><span>3. تقدير التكلفة</span></span>
<span class="line"><span>4. تحديد مؤشرات التحقق</span></span></code></pre></div><p><strong>الإجراء:</strong></p><ul><li>ما صعوبة التنفيذ التقني؟</li><li>ما تكلفة إنتاج المحتوى؟</li><li>ما تكلفة الترويج؟</li><li>ما صعوبة اكتساب المستخدمين؟</li></ul><p><strong>نص التلميح:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>أنا قلق بشأن:</span></span>
<span class="line"><span>1. [المخاوف 1]</span></span>
<span class="line"><span>2. [المخاوف 2]</span></span>
<span class="line"><span>3. [المخاوف 3]</span></span></code></pre></div><p><strong>الإجراء:</strong></p><ul><li>تقديم نصائح محددة لمعالجة مخاوفك</li><li>مقارنة بين عدة حلول واختيار الأفضل</li><li>تقدير التكلفة</li></ul><p><strong>نص التلميح:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بالنسبة لمخاوفي، يرجى تقديم حلول محددة.</span></span></code></pre></div><p><strong>الإجراء:</strong></p><ul><li>تنظيم خطة عمل واضحة</li><li>تحديد مؤشرات التحقق</li><li>إذا لم يتم تحقيقها، تعديل المسار في الوقت المناسب</li></ul><p><strong>نص التلميح:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>يرجى مساعدتي في تنظيم خطة عمل واضحة.</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">مهارات أساسية</p><ul><li><strong>محادثات متعددة:</strong> لا تتوقع الحصول على إجابة مثالية في محادثة واحدة، كرر العملية عدة مرات</li><li><strong>توفير المعلومات:</strong> أخبر الذكاء الاصطناعي بملاحظاتك وتجاربك وردود الفعل من الأشخاص من حولك</li><li><strong>تحدي الذكاء الاصطناعي:</strong> إذا كانت اقتراحات الذكاء الاصطناعي غير منطقية، أشر إلى ذلك فورًا</li><li><strong>التركيز على التنفيذ:</strong> في النهاية، يجب أن تؤدي العملية إلى خطة عمل محددة</li></ul></div><hr><h3 id="الملحق-و-قائمة-التحقق-من-المتطلبات" tabindex="-1">الملحق و: قائمة التحقق من المتطلبات <a class="header-anchor" href="#الملحق-و-قائمة-التحقق-من-المتطلبات" aria-label="Permalink to “الملحق و: قائمة التحقق من المتطلبات”">​</a></h3><p>قبل أن تقرر قضاء الوقت في التطوير، استخدم القائمة التالية للتحقق من فكرتك——<strong>السؤال الجوهري هو: هل سيدفع المستخدم مقابل هذا؟</strong></p><div class="tip custom-block"><p class="custom-block-title">قائمة التحقق من المتطلبات</p><p><strong>1. وضوح شخصية المستخدم</strong></p><ul><li>☐ هل يمكنك وصف المستخدم المستهدف في جملة واحدة؟</li><li>☐ هل يمكنك ذكر ما هي بدائلهم الحالية؟</li><li>☐ هل يمكنك وصف التفاصيل الدقيقة لسيناريو استخدامهم؟</li><li>☐ هل تمتلك هذه الفئة القدرة على الدفع؟</li></ul><p><strong>2. تقييم قوة نقطة الألم</strong></p><ul><li>☐ ما الثمن الذي يدفعه المستخدم حاليًا لحل هذه المشكلة؟ (الوقت/المال/الجهد)</li><li>☐ ما هي العواقب إذا لم يتم حل هذه المشكلة؟</li><li>☐ هل يبحث المستخدمون بالفعل عن حلول؟</li><li>☐ كم يرغب المستخدم في الدفع لحل هذه المشكلة؟</li></ul><p><strong>3. التمايز في الحل</strong></p><ul><li>☐ مقارنة بالحلول الحالية، ما هي مزاياك؟</li><li>☐ هل هذه الميزة كافية لجعل المستخدمين على استعداد للتحول؟</li><li>☐ ما مدى صعوبة نسخ ميزتك من قبل المنصات الكبرى؟</li><li>☐ هل تمايزك كافٍ لدفع المستخدمين مقابل الخدمة؟</li></ul><p><strong>4. جدوى نموذج العمل</strong></p><ul><li>☐ هل المستخدمون على استعداد للدفع مقابل هذا؟ كم سيدفعون؟ (يجب إجراء اختبار فعلي)</li><li>☐ ما هو التكلفة التقريبية للاستحواذ على عميل؟</li><li>☐ هل يمكن لقيمة دورة حياة العميل (LTV) أن تغطي تكلفة الاستحواذ على العملاء (CAC)؟</li><li>☐ هل هناك طرق أخرى لتحقيق الدخل؟ (الإعلانات، الخدمات المتميزة، قطاع الأعمال B2B، إلخ)</li></ul><p><strong>5. خطة التحقق السريع</strong></p><ul><li>☐ هل يمكنك بناء نموذج أولي قابل للاختبار بأقل تكلفة (في غضون 1-2 أسبوع)؟</li><li>☐ هل يمكنك العثور على 10 مستخدمين مستهدفين لإجراء مقابلات معهم؟</li><li>☐ هل يمكنك تصميم تجربة للتحقق من الفرضية الأساسية؟</li><li>☐ هل يمكنك جعل المستخدمين يدفعون دفعة مقدمة للتحقق من رغبتهم في الدفع؟</li></ul></div><p><strong>لا تسأل &quot;هل ستستخدم هذا المنتج؟&quot;</strong> هذا النوع من الأسئلة يجلب دائمًا إجابات إيجابية كاذبة.</p><p><strong>بل اسأل:</strong></p><ul><li>&quot;كيف تحل هذه المشكلة حاليًا؟&quot; (لفهم السلوك الحقيقي)</li><li>&quot;خلال الأسبوع الماضي، كم مرة أزعجتك هذه المشكلة؟&quot; (لفهم التكرار)</li><li>&quot;إذا كان هناك حل، لكنه يتطلب منك تغيير عاداتك الحالية، هل ستوافق؟&quot; (لفهم تكلفة التغيير)</li><li>&quot;إذا كان السعر XX ريال، هل ستشتريه؟&quot; (لفهم نية الدفع)</li></ul><p><strong>أفضل طريقة للتحقق:</strong> اطلب من المستخدمين دفع عربون. الكثيرون يقولون إنهم على استعداد للدفع، لكن من يدفعون المال فعلًا هم مستخدموك المستهدفون.</p><p><strong>المؤشرات الرئيسية:</strong></p><ul><li>نسبة المستخدمين المستعدين لدفع عربون &gt; 10%: الطلب حقيقي، ويستحق الاستثمار</li><li>نسبة المستخدمين المستعدين لدفع عربون 5-10%: الطلب موجود، لكن يحتاج إلى صقل</li><li>نسبة المستخدمين المستعدين لدفع عربون &lt; 5%: الطلب غير حقيقي، أو أن مفهوم المنتج به مشكلة</li></ul><hr><h2 id="ملخص-الفصل" tabindex="-1">ملخص الفصل <a class="header-anchor" href="#ملخص-الفصل" aria-label="Permalink to “ملخص الفصل”">​</a></h2><p>في هذا الفصل، من خلال قصة شياو مينغ، تعلمنا كيفية تقييم أفكار المنتجات من منظور مدير المنتج — <strong>الجوهر يدور دائمًا حول: هل سيدفع المستخدمون مقابل هذا؟</strong></p><div class="info custom-block"><p class="custom-block-title">النقاط الجوهرية</p><p><strong>1. المعايير الثلاثة للطلب الحقيقي:</strong></p><ul><li>المستخدمون على استعداد للدفع مقابلها (المعيار الأهم)</li><li>المستخدمون على استعداد لتغيير سلوكهم من أجلها</li><li>في غياب الحل، سيتكبد المستخدمون خسائر كبيرة</li></ul><p><strong>2. المسار من الفكرة العادية إلى منتج يدفع الناس مقابله:</strong></p><ul><li><strong>التقسيم الأفقي:</strong> إيجاد فئة محددة، وكلما كانت أكثر تحديدًا زادت نية الدفع</li><li><strong>الحفر العمودي:</strong> فهم السيناريو الكامل، وحل المشاعر وليس فقط الوظائف</li><li><strong>إعادة بناء القيمة:</strong> التطور من مجرد أداة إلى حل متكامل، وبناء مبرر للدفع</li></ul><p><strong>3. تجنب فخ الطلب المزيف:</strong></p><ul><li>حل نقطة ألم وهمية (حكة وليست نقطة ألم حقيقية)</li><li>حجم السوق صغير جدًا، ولا يمكنه دعم نموذج عمل</li><li>الحل أكثر تعقيدًا من المشكلة نفسها</li></ul><p><strong>4. طرق التحقق من نية الدفع:</strong></p><ul><li>إجراء مقابلات متعمقة مع 10 مستخدمين مستهدفين</li><li>جعل المستخدمين يدفعون دفعة مقدمة للتحقق من نيتهم الحقيقية</li><li>نسبة المستخدمين المستعدين لدفع عربون &gt; 10% فقط هي التي تستحق الاستثمار</li></ul><p><strong>5. استخدام محادثات AI لصقل مفهوم المنتج:</strong></p><ul><li>التكرار المتعدد، والتحسين المستمر</li><li>التركيز على التنفيذ، والوصول إلى خطة عمل</li><li>تحديد مؤشرات التحقق، والتعديل في الوقت المناسب</li></ul></div><p><strong>تذكر:</strong> مدير المنتج الجيد لا يخلق الطلب من العدم، بل يكتشف الطلبات الحقيقية <strong>المتجاهلة، والمُقلل من شأنها، أو التي تم تلبيتها بشكل خاطئ</strong>، ويجد طريقة تجعل المستخدمين على استعداد للدفع مقابلها.</p><p>في الفصل التالي، سنتخذ أفكارنا التي تم التحقق منها، ونبدأ في تعلم كيفية استخدام AI IDE لتحويلها إلى نموذج أولي تفاعلي للمنتج.</p>`,336))])}}});export{m as __pageData,f as default};
